insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('parent-routine-builder', 'Parent Routine Builder', 'worksheet'::resource_kind, 'A page for building morning and bedtime routines with the child''s input.', 'Use it to help a parent set up predictable routines the child helps shape.', array['Adults']::text[], '30 minutes', 'Walk through the morning and bedtime with the parent. List steps, then ask the child to add ideas. Use visual charts for young children. Start with one routine and expand later. Keep tone warm, not rigid.', '[{"id": "f0", "type": "textarea", "label": "Our morning steps"}, {"id": "f1", "type": "textarea", "label": "Our bedtime steps"}, {"id": "f2", "type": "textarea", "label": "What my child wants to add"}, {"id": "f3", "type": "textarea", "label": "Where we get stuck"}, {"id": "f4", "type": "textarea", "label": "A visual cue I will use"}, {"id": "f5", "type": "textarea", "label": "How I will praise effort"}]'::jsonb, array['parenting', 'routines', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('praise-jar-family-craft', 'Praise Jar Family Craft', 'kids'::resource_kind, 'A jar the family fills with notes of things that went well.', 'Use it to help a family notice and name effort.', array['Children']::text[], '25 minutes', 'The child decorates a jar and the parent writes or draws notes of effort. Read a few notes at dinner or bedtime. Tell the parent to praise specific actions. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw our jar"}, {"id": "f1", "type": "textarea", "label": "A note about something I did well"}, {"id": "f2", "type": "textarea", "label": "A note about my grown-up"}, {"id": "f3", "type": "textarea", "label": "How I felt reading notes"}, {"id": "f4", "type": "textarea", "label": "When we will read them"}]'::jsonb, array['parenting', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('calm-response-role-play-game', 'Calm Response Role Play Game', 'game'::resource_kind, 'Parents take turns drawing scenarios and practicing a calm response.', 'Use it to help parents rehearse calm replies to tough moments.', array['Adults', 'Groups']::text[], '35 minutes', 'Make cards of common moments like refusing homework. Parents take turns playing the child and the parent. Others give feedback on what worked. Debrief on what made calm hard and what helps. Allow passing.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "My calm response"}, {"id": "f2", "type": "textarea", "label": "What the group said helped"}, {"id": "f3", "type": "textarea", "label": "What was hardest"}, {"id": "f4", "type": "textarea", "label": "What I will try at home"}]'::jsonb, array['parenting', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('co-parent-alignment-conversation-sheet', 'Co-Parent Alignment Conversation Sheet', 'couples'::resource_kind, 'A sheet for co-parents to talk about rules, roles and support.', 'Use it to help co-parents get on the same page and support each other.', array['Couples']::text[], '40 minutes', 'Each parent lists the top three rules they care about. Compare lists and discuss where they differ with curiosity. Agree on a short plan and how to back each other up in front of the child. Raise only issues that are safe to discuss together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the three rules I care about most"}, {"id": "f1", "type": "textarea", "label": "Partner B: the three rules I care about most"}, {"id": "f2", "type": "textarea", "label": "Where we differ"}, {"id": "f3", "type": "textarea", "label": "What we agree on"}, {"id": "f4", "type": "textarea", "label": "How we back each other up"}, {"id": "f5", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['parenting', 'couples', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('validation-phrases-for-parents-practice', 'Validation Phrases for Parents Practice', 'dbt'::resource_kind, 'A practice sheet for validating a child''s feelings before problem solving.', 'Use it to help parents practice validating phrases.', array['Adults']::text[], '25 minutes', 'Share a short list of validating phrases and practice with real examples. Distinguish validation from agreeing or giving in. Have the parent role-play with you, then try it once at home.', '[{"id": "f0", "type": "textarea", "label": "A time my child was upset"}, {"id": "f1", "type": "textarea", "label": "What I usually say"}, {"id": "f2", "type": "textarea", "label": "A validating phrase I could use"}, {"id": "f3", "type": "textarea", "label": "What I want to do after validating"}, {"id": "f4", "type": "textarea", "label": "How it went when I tried"}]'::jsonb, array['parenting', 'core DBT', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('night-shift-sharing-and-rest-block-planner', 'Night Shift Sharing and Rest Block Planner', 'worksheet'::resource_kind, 'A planner for dividing nights and daytime rest among people who can help.', 'Use it to help a new parent find protected rest and support.', array['Adults', 'Couples']::text[], '30 minutes', 'List who can help and when, including partners, relatives and friends. Plan a block of rest for the client every day. Ask about what feels hard to ask for. If the client talks about thoughts of harming themselves or the baby, address it right away in session and share that 988 (call or text) is there any time.', '[{"id": "f0", "type": "textarea", "label": "People who can help"}, {"id": "f1", "type": "textarea", "label": "Times I need rest most"}, {"id": "f2", "type": "textarea", "label": "A protected rest block"}, {"id": "f3", "type": "textarea", "label": "What I find hard to ask for"}, {"id": "f4", "type": "textarea", "label": "How I will ask"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('mom-guilt-thought-review', 'Mom Guilt Thought Review', 'cbt'::resource_kind, 'A review of guilt thoughts about parenting with a fairer look at standards.', 'Use it to help a parent look at guilt-driven thoughts about parenting.', array['Adults']::text[], '25 minutes', 'Collect the ''should'' thoughts the parent has about feeding, sleep or time. Ask where the standard comes from and how a friend would judge it. Write a fairer thought. Avoid arguing the parent out of feelings.', '[{"id": "f0", "type": "textarea", "label": "The guilt thought"}, {"id": "f1", "type": "textarea", "label": "Where the standard comes from"}, {"id": "f2", "type": "textarea", "label": "What I would tell a friend"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What I will do for myself"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('new-baby-roles-and-appreciation-talk', 'New Baby Roles and Appreciation Talk', 'couples'::resource_kind, 'A conversation guide for two partners adjusting to a new baby.', 'Use it to help partners share the load and notice each other''s efforts.', array['Couples']::text[], '40 minutes', 'Each partner lists what they are carrying and what they appreciate in the other. Then plan one change. Keep it kind. Encourage them to name needs rather than keep score.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I carry"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I carry"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I appreciate"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I appreciate"}, {"id": "f4", "type": "textarea", "label": "One change we will try"}, {"id": "f5", "type": "textarea", "label": "When we will talk again"}]'::jsonb, array['perinatal and postpartum', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('values-in-the-fog-of-new-parenthood-page', 'Values in the Fog of New Parenthood Page', 'act'::resource_kind, 'A page for naming what matters now and tiny actions that fit.', 'Use it to help a parent connect with values when time and energy are scarce.', array['Adults']::text[], '25 minutes', 'Ask the parent what kind of parent and person they want to be. Choose one tiny action per day. Accept that some days will be survival. Check in on feelings and ask about safety when needed, mentioning 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "What I value as a parent"}, {"id": "f1", "type": "textarea", "label": "What I value as a person"}, {"id": "f2", "type": "textarea", "label": "A tiny action for today"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will be kind to myself"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('soothe-myself-between-feedings-plan', 'Soothe Myself Between Feedings Plan', 'dbt'::resource_kind, 'A plan of self-soothing through the senses for short breaks.', 'Use it to help a parent calm themselves in small windows.', array['Adults']::text[], '20 minutes', 'List sensory comforts that take under five minutes. Choose one for each of the five senses. Practice one in session. Ask where the parent can keep a small comfort kit.', '[{"id": "f0", "type": "textarea", "label": "Something to see that soothes me"}, {"id": "f1", "type": "textarea", "label": "Something to hear"}, {"id": "f2", "type": "textarea", "label": "Something to touch"}, {"id": "f3", "type": "textarea", "label": "Something to smell or taste"}, {"id": "f4", "type": "textarea", "label": "Where I will keep it"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'distress tolerance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('core-belief-evidence-journal', 'Core Belief Evidence Journal', 'cbt'::resource_kind, 'A journal collecting evidence that supports a kinder belief about oneself.', 'Use it to help a client build a fairer view of themselves over time.', array['Adults']::text[], 'Five minutes daily', 'Choose one harsh belief and a more balanced one. Each day the client writes a piece of evidence for the balanced belief. Be patient; beliefs shift slowly. Review entries and celebrate small shifts.', '[{"id": "f0", "type": "textarea", "label": "The harsh belief"}, {"id": "f1", "type": "textarea", "label": "A kinder belief I want to test"}, {"id": "f2", "type": "textarea", "label": "Evidence today for the kinder belief"}, {"id": "f3", "type": "textarea", "label": "How much I believe it from 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I will look for tomorrow"}]'::jsonb, array['self-esteem', 'core CBT', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('self-worth-is-not-a-report-card-page', 'Self-Worth Is Not a Report Card Page', 'act'::resource_kind, 'A page separating worth from performance and linking to values.', 'Use it to help a client act on values without needing a perfect score.', array['Adults']::text[], '25 minutes', 'Ask where the client learned to measure worth by results. Name a value and an action that matters regardless of outcome. Keep the tone gentle.', '[{"id": "f0", "type": "textarea", "label": "How I measure my worth"}, {"id": "f1", "type": "textarea", "label": "Where I learned that"}, {"id": "f2", "type": "textarea", "label": "What I value that is not a result"}, {"id": "f3", "type": "textarea", "label": "An action I can take no matter the outcome"}, {"id": "f4", "type": "textarea", "label": "What I say to myself when I fall short"}]'::jsonb, array['self-esteem', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('i-am-great-at-poster', 'I Am Great At Poster', 'kids'::resource_kind, 'The child makes a poster of strengths with the help of a parent''s words.', 'Use it to help a child see what they do well.', array['Children']::text[], '30 minutes', 'The child writes or draws strengths on a poster and the parent adds a note. Display it at home. Tell the parent to praise effort and character. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my poster"}, {"id": "f1", "type": "textarea", "label": "Three things I am good at"}, {"id": "f2", "type": "textarea", "label": "Something kind I did"}, {"id": "f3", "type": "textarea", "label": "What my grown-up says about me"}, {"id": "f4", "type": "textarea", "label": "Where I will hang it"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('strength-spotting-circle-game', 'Strength Spotting Circle Game', 'game'::resource_kind, 'Players spot strengths in each other with cards and give appreciations.', 'Use it to help a group notice and accept strengths.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Each player draws a strength card and offers a real appreciation to another. The receiver says thank you. Debrief on how it felt to give and to receive. Make passing available.', '[{"id": "f0", "type": "textarea", "label": "The strength I spotted"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "What I heard about myself"}, {"id": "f3", "type": "textarea", "label": "How it felt to receive"}, {"id": "f4", "type": "textarea", "label": "One strength I will own"}]'::jsonb, array['self-esteem', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('inner-critic-interview-page', 'Inner Critic Interview Page', 'worksheet'::resource_kind, 'An interview with the inner critic: what it says, why and what it is afraid of.', 'Use it to help a client understand the intent behind the critic.', array['Adults']::text[], '25 minutes', 'Ask the client to give the critic a name and ask what it wants. Often it is protecting. Then ask what a gentler coach would say. Do not try to silence it.', '[{"id": "f0", "type": "textarea", "label": "The name of my critic"}, {"id": "f1", "type": "textarea", "label": "What it says most"}, {"id": "f2", "type": "textarea", "label": "What it is trying to protect me from"}, {"id": "f3", "type": "textarea", "label": "What it costs me"}, {"id": "f4", "type": "textarea", "label": "What a kind coach would say"}]'::jsonb, array['self-esteem', 'self-compassion', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('social-prediction-test-sheet', 'Social Prediction Test Sheet', 'cbt'::resource_kind, 'A sheet for predicting how a social situation will go, then testing it.', 'Use it to help a client check predictions against what happens.', array['Adults']::text[], 'Full session', 'Pick a small social task. Record predictions, safety behaviors and outcomes. Ask what the client noticed about others. Keep tasks gradual and agreed on.', '[{"id": "f0", "type": "textarea", "label": "The social situation"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "Safety behaviors I will drop"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I noticed about other people"}, {"id": "f5", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('connection-value-single-step-page', 'Connection Value Single Step Page', 'act'::resource_kind, 'A page for choosing connection as a value and one step despite fear.', 'Use it to help a client move toward connection while anxious.', array['Adults']::text[], '25 minutes', 'Ask what connection means to the client. Pick a step like greeting someone. Name the thoughts that will come and decide to carry them. Review what happened.', '[{"id": "f0", "type": "textarea", "label": "What connection means to me"}, {"id": "f1", "type": "textarea", "label": "A small social step"}, {"id": "f2", "type": "textarea", "label": "Thoughts that will come"}, {"id": "f3", "type": "textarea", "label": "Feelings I will carry"}, {"id": "f4", "type": "textarea", "label": "What I did"}, {"id": "f5", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('opener-and-follow-up-pairing-game', 'Opener and Follow-Up Pairing Game', 'game'::resource_kind, 'Players practice starters and follow-up questions with cards.', 'Use it to help players try conversation starters in a low-stakes game.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make cards with openers and follow-ups. Players pair up and practice for two minutes, then swap. Debrief on what felt natural. Passing is fine.', '[{"id": "f0", "type": "textarea", "label": "The opener I drew"}, {"id": "f1", "type": "textarea", "label": "How the chat went"}, {"id": "f2", "type": "textarea", "label": "A follow-up I liked"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "Where I will use it"}]'::jsonb, array['social anxiety', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('attention-inside-and-out-experiment-page', 'Attention Inside and Out Experiment Page', 'worksheet'::resource_kind, 'A page comparing focusing on oneself with focusing on the other person.', 'Use it to help a client notice how self-focus affects anxiety in conversation.', array['Adults']::text[], '25 minutes', 'Run a short conversation in session twice, once focusing inward and once outward. Rate anxiety and connection each time. Discuss what changed. Repeat outside session.', '[{"id": "f0", "type": "textarea", "label": "How I felt focusing on myself"}, {"id": "f1", "type": "textarea", "label": "How I felt focusing on the other person"}, {"id": "f2", "type": "textarea", "label": "What I noticed about the conversation"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "Where I will practice"}]'::jsonb, array['social anxiety', 'attention', 'behavioral experiment']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('interpersonal-confidence-script-card', 'Interpersonal Confidence Script Card', 'dbt'::resource_kind, 'A card with short scripts for asking, saying no and joining a group.', 'Use it to give a client words to use in social moments.', array['Adults', 'Teens']::text[], '30 minutes', 'Draft scripts with the client using DEAR MAN steps. Practice in role play. Keep scripts short and in their own voice. Give feedback on tone.', '[{"id": "f0", "type": "textarea", "label": "A situation where I want to speak up"}, {"id": "f1", "type": "textarea", "label": "What I want to say"}, {"id": "f2", "type": "textarea", "label": "How I will say it"}, {"id": "f3", "type": "textarea", "label": "My tone and posture"}, {"id": "f4", "type": "textarea", "label": "How it went in practice"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'DEAR MAN']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grief-wave-notes', 'Grief Wave Notes', 'worksheet'::resource_kind, 'A page for noticing grief waves, what set them off and what helped.', 'Use it to help a client see grief as something that comes and goes.', array['Adults']::text[], '20 minutes', 'Ask the client to record when waves come and what comforts. Normalize that grief has no schedule. Do not push toward closure. Ask about safety if the client feels hopeless and share that 988 (call or text) is open any time.', '[{"id": "f0", "type": "textarea", "label": "When a wave came"}, {"id": "f1", "type": "textarea", "label": "What set it off"}, {"id": "f2", "type": "textarea", "label": "What it felt like"}, {"id": "f3", "type": "textarea", "label": "What helped"}, {"id": "f4", "type": "textarea", "label": "Who I reached out to"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['grief and loss', 'support', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-i-loved-and-how-i-honor-it-page', 'What I Loved and How I Honor It Page', 'act'::resource_kind, 'A page linking what the client loved about the person with ways to honor it.', 'Use it to help a client carry values and love forward after a loss.', array['Adults']::text[], '30 minutes', 'Ask what the person valued and what the client values about them. Choose one small act that honors that. Let the client set the pace and allow tears.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them"}, {"id": "f1", "type": "textarea", "label": "What they valued"}, {"id": "f2", "type": "textarea", "label": "A way to honor that"}, {"id": "f3", "type": "textarea", "label": "What makes it hard"}, {"id": "f4", "type": "textarea", "label": "What I will do and when"}]'::jsonb, array['grief and loss', 'values', 'connection']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('keepsake-box-for-a-missed-person-or-pet', 'Keepsake Box for a Missed Person or Pet', 'kids'::resource_kind, 'The child decorates a box and fills it with drawings and keepsakes of someone they miss.', 'Use it to give a child a safe way to remember a person or pet.', array['Children']::text[], '30 minutes', 'The child decorates a box and picks items. Let them talk or stay quiet. Tell the parent that questions and repeated sadness are common and to answer honestly in simple words. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my memory box"}, {"id": "f1", "type": "textarea", "label": "What I put in it"}, {"id": "f2", "type": "textarea", "label": "A good memory"}, {"id": "f3", "type": "textarea", "label": "How I feel today"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('two-ways-of-mourning-partner-talk-guide', 'Two Ways of Mourning Partner Talk Guide', 'couples'::resource_kind, 'A guide for partners who grieve in different ways to share and support.', 'Use it to help partners understand each other''s different grieving.', array['Couples']::text[], '40 minutes', 'Each partner describes how they grieve and what they need. Listen without comparing. Choose one shared ritual and one space for solo time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What I need from you"}, {"id": "f3", "type": "textarea", "label": "What I find hard to see in you"}, {"id": "f4", "type": "textarea", "label": "A shared ritual"}, {"id": "f5", "type": "textarea", "label": "A way to give each other space"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('story-stones-remembering-game', 'Story Stones Remembering Game', 'game'::resource_kind, 'Players choose stones with pictures and share a memory or feeling.', 'Use it to help a group remember and share at their own pace.', array['Adults', 'Groups']::text[], '30 minutes', 'Paint simple pictures on stones. Players draw one and share a memory if they wish. Others listen without fixing. Debrief on what it was like.', '[{"id": "f0", "type": "textarea", "label": "The stone I drew"}, {"id": "f1", "type": "textarea", "label": "The memory it brought"}, {"id": "f2", "type": "textarea", "label": "How I felt sharing"}, {"id": "f3", "type": "textarea", "label": "What I heard from others"}, {"id": "f4", "type": "textarea", "label": "What I will take with me"}]'::jsonb, array['grief and loss', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('softened-startup-practice-sheet', 'Softened Startup Practice Sheet', 'couples'::resource_kind, 'A sheet for rewording complaints into gentle requests.', 'Use it to help partners begin tough talks with less blame.', array['Couples']::text[], '30 minutes', 'Take a complaint and rewrite it as ''I feel... about... and I need...''. Practice aloud. Give feedback on tone. Note the difference in how it lands.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my complaint as I would usually say it"}, {"id": "f1", "type": "textarea", "label": "Partner A: my softened version"}, {"id": "f2", "type": "textarea", "label": "Partner B: my complaint as I would usually say it"}, {"id": "f3", "type": "textarea", "label": "Partner B: my softened version"}, {"id": "f4", "type": "textarea", "label": "How each version felt to hear"}]'::jsonb, array['relationship issues', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('dear-man-relationship-request-page', 'DEAR MAN Relationship Request Page', 'dbt'::resource_kind, 'A page for planning a clear, respectful request in a relationship.', 'Use it to help a client ask for what they need with skill.', array['Adults']::text[], '30 minutes', 'Walk through each step: Describe, Express, Assert, Reinforce, Mindful, Appear confident, Negotiate. Role play the request. Plan for different responses.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Describe the facts"}, {"id": "f2", "type": "textarea", "label": "Express my feelings"}, {"id": "f3", "type": "textarea", "label": "Assert what I ask"}, {"id": "f4", "type": "textarea", "label": "What I offer in return"}, {"id": "f5", "type": "textarea", "label": "How I will respond if they say no"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('guess-about-their-thoughts-ask-first-page', 'Guess About Their Thoughts Ask-First Page', 'cbt'::resource_kind, 'A page for catching assumptions about a partner''s thoughts and checking them.', 'Use it to help a client check guesses about what others think.', array['Adults']::text[], '20 minutes', 'List the assumption and how it affected behavior. Brainstorm other explanations. Plan a way to ask. Practice the question in session.', '[{"id": "f0", "type": "textarea", "label": "What I assumed"}, {"id": "f1", "type": "textarea", "label": "How it changed what I did"}, {"id": "f2", "type": "textarea", "label": "Other explanations"}, {"id": "f3", "type": "textarea", "label": "A question I can ask"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('needs-and-wants-trading-game', 'Needs and Wants Trading Game', 'game'::resource_kind, 'Players trade cards of needs and wants and discuss what they are willing to give.', 'Use it to help players talk about needs and compromise playfully.', array['Adults', 'Groups']::text[], '30 minutes', 'Make cards for needs like quiet time or affection. Players trade with partners and explain choices. Debrief on what was hard to give or ask. Keep it kind.', '[{"id": "f0", "type": "textarea", "label": "The cards I traded"}, {"id": "f1", "type": "textarea", "label": "What I asked for"}, {"id": "f2", "type": "textarea", "label": "What I gave"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "What I will try in real life"}]'::jsonb, array['relationship issues', 'game', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('closeness-and-conflict-patterns-strip', 'Closeness and Conflict Patterns Strip', 'worksheet'::resource_kind, 'A timeline of how the client has acted in past relationships and what they want next.', 'Use it to help a client see patterns and choose different steps.', array['Adults']::text[], '35 minutes', 'Ask for a few moments, not full histories. Notice patterns in how they handle closeness and conflict. Focus on what they want now and one new step.', '[{"id": "f0", "type": "textarea", "label": "Moments that stand out"}, {"id": "f1", "type": "textarea", "label": "Patterns I notice"}, {"id": "f2", "type": "textarea", "label": "What I did well"}, {"id": "f3", "type": "textarea", "label": "What I want to do differently"}, {"id": "f4", "type": "textarea", "label": "One new step"}]'::jsonb, array['relationship issues', 'patterns', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('today-s-safe-people-and-places-plan-page', 'Today''s Safe People and Places Plan Page', 'worksheet'::resource_kind, 'A page naming safe people, places and steps without recounting any events.', 'Use it to help a client build a current-day plan for safety and support.', array['Adults', 'Teens']::text[], '30 minutes', 'Focus on the present: who is safe, where, and what to do when feeling unsafe. Never ask for details of the past. Check reporting duties if the client is a minor. Share that 988 (call or text) is available any time, and RAINN at 800-656-4673.', '[{"id": "f0", "type": "textarea", "label": "People I trust"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe"}, {"id": "f2", "type": "textarea", "label": "What I do when I feel unsafe"}, {"id": "f3", "type": "textarea", "label": "Who I can call"}, {"id": "f4", "type": "textarea", "label": "Steps for a hard day"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grounding-and-pacing-skills-menu', 'Grounding and Pacing Skills Menu', 'dbt'::resource_kind, 'A menu of grounding and pacing skills to use before and after session.', 'Use it to help a client slow down and stay present.', array['Adults']::text[], '25 minutes', 'Try several skills in session and let the client rate them. Agree on a pace and a stop signal. Nothing here asks for details of what happened. Check in at the end.', '[{"id": "f0", "type": "textarea", "label": "Skills that ground me"}, {"id": "f1", "type": "textarea", "label": "Skills that help me slow down"}, {"id": "f2", "type": "textarea", "label": "My stop signal"}, {"id": "f3", "type": "textarea", "label": "What I do after a session"}, {"id": "f4", "type": "textarea", "label": "Who I can contact"}]'::jsonb, array['sexual abuse', 'grounding', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('reclaiming-choices-values-page', 'Reclaiming Choices Values Page', 'act'::resource_kind, 'A page about choices the client can make now that fit their values.', 'Use it to help a client notice choice and agency in daily life.', array['Adults']::text[], '30 minutes', 'Invite the client to list small daily choices that are theirs. Link to values. Go slowly and let them skip anything. Never ask about past events.', '[{"id": "f0", "type": "textarea", "label": "Small choices that are mine"}, {"id": "f1", "type": "textarea", "label": "What I value"}, {"id": "f2", "type": "textarea", "label": "A choice I want to make this week"}, {"id": "f3", "type": "textarea", "label": "What supports me"}, {"id": "f4", "type": "textarea", "label": "What I will do if it feels hard"}]'::jsonb, array['sexual abuse', 'values', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-safety-rules-drawing', 'Body Safety Rules Drawing', 'kids'::resource_kind, 'The child draws the people and rules that keep their body safe and who to tell.', 'Use it to help a child learn safety rules and trusted adults.', array['Children']::text[], '25 minutes', 'Use simple, age-appropriate language: my body belongs to me, and I can always tell a trusted adult. Do not ask for details. Tell the parent how to respond calmly if a child shares. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw me and my safe grown-ups"}, {"id": "f1", "type": "textarea", "label": "Who I can tell"}, {"id": "f2", "type": "textarea", "label": "The rule about my body"}, {"id": "f3", "type": "textarea", "label": "What I do if someone makes me feel unsafe"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fair-thoughts-about-blame-cards', 'Fair Thoughts About Blame Cards', 'cbt'::resource_kind, 'Cards for gently looking at self-blame thoughts and finding fairer ones.', 'Use it to help a client meet self-blame thoughts with kindness.', array['Adults']::text[], '25 minutes', 'Work only with thoughts, not events. Ask the client what they would tell a friend. Write a fairer thought and practice reading it. Skip if the client feels unsteady. Share that 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "A blame thought that visits me"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f2", "type": "textarea", "label": "A fairer thought"}, {"id": "f3", "type": "textarea", "label": "How I feel reading it"}, {"id": "f4", "type": "textarea", "label": "Who supports me"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('tipp-skills-practice-log', 'TIPP Skills Practice Log', 'dbt'::resource_kind, 'A log for practicing temperature, intense exercise, paced breathing and relaxation.', 'Use it to help a client try body-based skills for fast relief.', array['Adults']::text[], 'One week, ten minutes per entry', 'Teach each skill and rate it in session. Ask the client to log use and effect. Check for health issues before temperature or exercise skills.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Which TIPP skill I used"}, {"id": "f2", "type": "textarea", "label": "Distress before"}, {"id": "f3", "type": "textarea", "label": "Distress after"}, {"id": "f4", "type": "textarea", "label": "What I would change"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('room-hunt-for-everyday-calm-tools', 'Room Hunt for Everyday Calm Tools', 'game'::resource_kind, 'Players hunt for items and places that support coping skills and share how they use them.', 'Use it to help players find coping tools around them.', array['Teens', 'Adults', 'Groups']::text[], '35 minutes', 'Make a list like something soft, something that smells nice, a quiet spot. Players find them and explain use. Debrief on which they will use.', '[{"id": "f0", "type": "textarea", "label": "What I found"}, {"id": "f1", "type": "textarea", "label": "How I could use it"}, {"id": "f2", "type": "textarea", "label": "What surprised me"}, {"id": "f3", "type": "textarea", "label": "What I will keep"}, {"id": "f4", "type": "textarea", "label": "Where I will use it"}]'::jsonb, array['coping skills', 'game', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('decorate-and-fill-my-calm-tool-box', 'Decorate and Fill My Calm Tool Box', 'kids'::resource_kind, 'The child decorates a box and fills it with coping tools they pick.', 'Use it to help a child build a personal set of coping tools.', array['Children']::text[], '30 minutes', 'The child decorates a box and adds drawings or small items like a stress ball. Practice using each. Tell the parent to keep it handy. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my toolbox"}, {"id": "f1", "type": "textarea", "label": "Tools I put in"}, {"id": "f2", "type": "textarea", "label": "Which tool I use first"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}, {"id": "f4", "type": "textarea", "label": "How my grown-up helps"}]'::jsonb, array['coping skills', 'children', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('hard-moment-to-skill-pairing-chart', 'Hard Moment to Skill Pairing Chart', 'worksheet'::resource_kind, 'A chart matching feelings and situations with coping skills.', 'Use it to help a client match skills to what they face.', array['Adults', 'Teens']::text[], '25 minutes', 'List common difficult moments and brainstorm skills. Rate each match from 0 to 10. Revise after trying them.', '[{"id": "f0", "type": "textarea", "label": "A hard situation"}, {"id": "f1", "type": "textarea", "label": "Skills that might fit"}, {"id": "f2", "type": "textarea", "label": "My rating of each"}, {"id": "f3", "type": "textarea", "label": "The one I will try"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['coping skills', 'skills', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('willingness-to-feel-practice-page', 'Willingness to Feel Practice Page', 'act'::resource_kind, 'A page practicing making room for a feeling for a short time.', 'Use it to help a client build willingness to feel without escape.', array['Adults']::text[], '20 minutes', 'Choose a mild feeling and have the client stay with it for a minute, noticing sensations. Rate willingness. Debrief gently.', '[{"id": "f0", "type": "textarea", "label": "The feeling I picked"}, {"id": "f1", "type": "textarea", "label": "Where I notice it"}, {"id": "f2", "type": "textarea", "label": "How willing I was"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "How I might use this"}]'::jsonb, array['coping skills', 'willingness', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('feared-situations-rung-ranking-page', 'Feared Situations Rung Ranking Page', 'cbt'::resource_kind, 'A ladder of feared situations ranked from easiest to hardest.', 'Use it to help a client plan gradual steps toward a feared situation.', array['Adults']::text[], 'Full session', 'List situations and rate fear for each. Pick a first step that is challenging but doable. Plan how to stay in it. Agree on pacing together.', '[{"id": "f0", "type": "textarea", "label": "The fear I want to work on"}, {"id": "f1", "type": "textarea", "label": "Situations ranked by fear"}, {"id": "f2", "type": "textarea", "label": "My first step"}, {"id": "f3", "type": "textarea", "label": "How long I will stay"}, {"id": "f4", "type": "textarea", "label": "What I notice after"}]'::jsonb, array['phobias', 'exposure', 'avoidance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('sticker-ladder-of-brave-small-steps', 'Sticker Ladder of Brave Small Steps', 'kids'::resource_kind, 'The child decorates a ladder with small brave steps and stickers.', 'Use it to help a child take small steps toward something scary.', array['Children']::text[], '25 minutes', 'The child draws a ladder with steps from easy to hard. Add stickers after each step. Tell the parent to cheer effort and never force a step. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my ladder"}, {"id": "f1", "type": "textarea", "label": "My first step"}, {"id": "f2", "type": "textarea", "label": "Who helps me"}, {"id": "f3", "type": "textarea", "label": "How I feel after a step"}, {"id": "f4", "type": "textarea", "label": "What I get to do after"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fear-facing-board-game', 'Fear Facing Board Game', 'game'::resource_kind, 'Players move along a board and take on small fear-facing challenges.', 'Use it to help a group try small exposures with support.', array['Teens', 'Adults', 'Groups']::text[], '40 minutes', 'Create a board with challenge squares at mild levels. Players choose challenges and cheer each other. Debrief on what it was like. Always allow a pass.', '[{"id": "f0", "type": "textarea", "label": "The challenge I took"}, {"id": "f1", "type": "textarea", "label": "How scared I felt"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "The next challenge"}]'::jsonb, array['phobias', 'game', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-i-skip-because-of-fear-map', 'What I Skip Because of Fear Map', 'worksheet'::resource_kind, 'A map of things the client avoids because of a fear and what it costs.', 'Use it to help a client see how avoidance shapes daily life.', array['Adults']::text[], '25 minutes', 'List places and activities avoided. Ask what each costs. Choose one to work toward. Keep non-judgmental.', '[{"id": "f0", "type": "textarea", "label": "Things I avoid"}, {"id": "f1", "type": "textarea", "label": "What I miss out on"}, {"id": "f2", "type": "textarea", "label": "What I fear will happen"}, {"id": "f3", "type": "textarea", "label": "One thing I want back"}, {"id": "f4", "type": "textarea", "label": "A first step"}]'::jsonb, array['phobias', 'avoidance', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fear-and-values-crossroads-page', 'Fear and Values Crossroads Page', 'act'::resource_kind, 'A page for choosing values-led action when fear points elsewhere.', 'Use it to help a client choose a valued direction with fear present.', array['Adults']::text[], '25 minutes', 'Draw a crossroads with fear on one path and values on the other. Discuss what each gives. Choose a step and plan to carry the fear.', '[{"id": "f0", "type": "textarea", "label": "What fear tells me to do"}, {"id": "f1", "type": "textarea", "label": "What my values point to"}, {"id": "f2", "type": "textarea", "label": "The cost of each path"}, {"id": "f3", "type": "textarea", "label": "The step I will take"}, {"id": "f4", "type": "textarea", "label": "What I will carry with me"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-talk-thought-record', 'Body Talk Thought Record', 'cbt'::resource_kind, 'A thought record for noticing critical thoughts about the body and shifting them.', 'Use it to help a client catch critical body thoughts and find a fairer view.', array['Adults']::text[], '25 minutes', 'Ask the client to notice when body thoughts spike and what was happening. Write a fairer thought focusing on what the body does. Avoid discussing size, shape or appearance rules.', '[{"id": "f0", "type": "textarea", "label": "Where I was when the thought came"}, {"id": "f1", "type": "textarea", "label": "The thought"}, {"id": "f2", "type": "textarea", "label": "How it made me feel"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What my body did for me today"}]'::jsonb, array['body image', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-as-a-home-values-page', 'Body as a Home Values Page', 'act'::resource_kind, 'A page about caring for and appreciating the body as the home where life happens.', 'Use it to help a client act on values rather than appearance.', array['Adults']::text[], '25 minutes', 'Ask what the client''s body lets them do. Link to values and plan one caring act. Keep focus on function and care.', '[{"id": "f0", "type": "textarea", "label": "What my body lets me do"}, {"id": "f1", "type": "textarea", "label": "What I value"}, {"id": "f2", "type": "textarea", "label": "One caring act this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will notice"}]'::jsonb, array['body image', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-judgment-letting-go-practice', 'Body Judgment Letting-Go Practice', 'dbt'::resource_kind, 'A mindfulness practice for noticing body judgments without acting on them.', 'Use it to help a client observe judgments and return to the present.', array['Adults']::text[], '20 minutes', 'Teach non-judgmental stance. Have the client notice a judgment, label it ''judgment'' and return to the senses. Practice in session.', '[{"id": "f0", "type": "textarea", "label": "A judgment I noticed"}, {"id": "f1", "type": "textarea", "label": "How I labeled it"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my senses"}, {"id": "f3", "type": "textarea", "label": "How I returned"}, {"id": "f4", "type": "textarea", "label": "When I will practice"}]'::jsonb, array['body image', 'core DBT', 'mindfulness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('appreciation-for-who-we-are-exchange', 'Appreciation for Who We Are Exchange', 'couples'::resource_kind, 'Partners trade appreciation about character and shared moments, not looks.', 'Use it to help partners value each other beyond appearance.', array['Couples']::text[], '25 minutes', 'Each writes appreciations about qualities and actions. Read aloud and receive. Debrief on what it felt like. Keep appearance out.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciate about my partner"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciate about my partner"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear"}, {"id": "f3", "type": "textarea", "label": "A moment I treasure"}, {"id": "f4", "type": "textarea", "label": "How we will keep it up"}]'::jsonb, array['body image', 'couples', 'connection']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-my-body-does-collage', 'What My Body Does Collage', 'kids'::resource_kind, 'The child makes a collage of all the things their body does and loves.', 'Use it to help a child value what their body can do.', array['Children']::text[], '30 minutes', 'The child cuts pictures or draws activities like running, hugging and laughing. Tell the parent to talk about what bodies do, not how they look. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my collage"}, {"id": "f1", "type": "textarea", "label": "Things my body does"}, {"id": "f2", "type": "textarea", "label": "My favorite"}, {"id": "f3", "type": "textarea", "label": "How my body helps me"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['body image', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('sunday-reset-planning-page', 'Sunday Reset Planning Page', 'worksheet'::resource_kind, 'A one-page planner for choosing three priorities and one restful thing before the week starts.', 'Use it to help a client enter the week with a short, realistic plan.', array['Adults']::text[], '20 minutes', 'Sit with the client on a Sunday-style plan using last week as the example. Keep the list to three priorities so the page does not become one more demand. Ask what rest will actually be protected, and look at the page together at the next session.', '[{"id": "f0", "type": "textarea", "label": "What matters most this coming week (three things at most)?"}, {"id": "f1", "type": "textarea", "label": "What could get in the way of each one?"}, {"id": "f2", "type": "textarea", "label": "One restful thing I will protect on my calendar:"}, {"id": "f3", "type": "textarea", "label": "What I am deliberately leaving off this week:"}]'::jsonb, array['planning', 'routines']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('small-wins-collection-sheet', 'Small Wins Collection Sheet', 'worksheet'::resource_kind, 'A running page for writing down small things that went right, with what the client did to help them happen.', 'Use it to help a client notice effort and progress that usually goes unnamed.', array['Adults', 'Teens']::text[], 'Five minutes daily for a week', 'Ask for one entry a day, however small. Clients who discount wins often need an example from you first, such as answering a hard email. Read it back aloud in session and ask which entry they would tell a friend about.', '[{"id": "f0", "type": "textarea", "label": "Something that went okay today:"}, {"id": "f1", "type": "textarea", "label": "What I did that helped it happen:"}, {"id": "f2", "type": "textarea", "label": "How I felt noticing it:"}, {"id": "f3", "type": "textarea", "label": "A small win I almost skipped over:"}]'::jsonb, array['strengths', 'self-monitoring']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('weekly-calendar-audit-page', 'Weekly Calendar Audit Page', 'worksheet'::resource_kind, 'A page for sorting last week''s calendar into must-do, chosen and drifted-into time.', 'Use it to help a client see where their hours went and what they would change.', array['Adults']::text[], '30 minutes', 'Work from the client''s real calendar or phone, not memory. The three columns give you something concrete to explore without judgment. Choose one item to move, shrink or drop, and ask what makes that change hard.', '[{"id": "f0", "type": "textarea", "label": "Things I had to do last week:"}, {"id": "f1", "type": "textarea", "label": "Things I chose to do and was glad I did:"}, {"id": "f2", "type": "textarea", "label": "Things I drifted into and would rather skip:"}, {"id": "f3", "type": "textarea", "label": "One change I will try next week:"}]'::jsonb, array['planning', 'habits']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('needs-and-requests-sorting-page', 'Needs and Requests Sorting Page', 'worksheet'::resource_kind, 'A sheet that separates what a client needs, what they could ask for and who they could ask.', 'Use it to help a client turn an unspoken need into a specific request.', array['Adults']::text[], '25 minutes', 'Many clients can name what is wrong but not what they would like instead. Have them list needs first, then sort into ones they can meet alone and ones that involve another person. Rehearse the first request aloud in session.', '[{"id": "f0", "type": "textarea", "label": "A need that has gone unmet lately:"}, {"id": "f1", "type": "textarea", "label": "Can I meet it on my own, or do I need someone else?"}, {"id": "f2", "type": "textarea", "label": "Who I could ask, and what I would say:"}, {"id": "f3", "type": "textarea", "label": "What I fear might happen if I ask:"}]'::jsonb, array['boundaries', 'communication']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('transition-day-checklist-builder', 'Transition Day Checklist Builder', 'worksheet'::resource_kind, 'A builder for a short checklist that eases a hard transition such as a move, new job or return from leave.', 'Use it to help a client break a big change into steps they can tick off.', array['Adults']::text[], '30 minutes', 'Pick one upcoming transition and let the client write the steps in their own words. Mark which steps are for the first day, first week and first month. Check back on which steps proved unnecessary so the list becomes lighter, not longer.', '[{"id": "f0", "type": "textarea", "label": "The change I am heading into:"}, {"id": "f1", "type": "textarea", "label": "Steps for the first day:"}, {"id": "f2", "type": "textarea", "label": "Steps for the first week:"}, {"id": "f3", "type": "textarea", "label": "Who or what will support me through it:"}]'::jsonb, array['planning', 'routines']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('thought-time-machine-sheet', 'Thought Time Machine Sheet', 'cbt'::resource_kind, 'A CBT sheet that asks how a worrying thought will look in a week, a year and five years.', 'Use it to help a client loosen the grip of a thought by changing the time frame.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a thought the client is stuck on and walk through the three time frames slowly. The shift in perspective is the point, not forcing a cheerful answer. Ask what they would say to a friend holding the same thought.', '[{"id": "f0", "type": "textarea", "label": "The thought and how strongly I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "How it might look in a week:"}, {"id": "f2", "type": "textarea", "label": "How it might look in a year:"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend, and how strongly I believe the thought now:"}]'::jsonb, array['core CBT', 'thinking traps']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-worksheet', 'Mind-Reading Check Worksheet', 'cbt'::resource_kind, 'A worksheet for testing a guess about what someone else thinks against the facts available.', 'Use it to help a client separate what they know about others from what they assume.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a recent moment when the client assumed what another person thought. Separate what was seen or heard from what was guessed. Plan one small, low-risk way to check the guess, such as a casual question.', '[{"id": "f0", "type": "textarea", "label": "What I think the other person thought:"}, {"id": "f1", "type": "textarea", "label": "What I actually saw or heard:"}, {"id": "f2", "type": "textarea", "label": "Other explanations that are possible:"}, {"id": "f3", "type": "textarea", "label": "One small way I could check:"}]'::jsonb, array['core CBT', 'thinking traps', 'evidence']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('rule-and-exception-hunt-sheet', 'Rule and Exception Hunt Sheet', 'cbt'::resource_kind, 'A CBT sheet for finding the strict personal rules behind distress and the times they have bent.', 'Use it to help a client see that a firm "should" has exceptions and costs.', array['Adults']::text[], '25 minutes', 'Listen for "should" and "must" in the client''s language and pick one rule to work on. Looking for exceptions is gentler than arguing with the rule. Ask what the rule costs them and what a flexible version might sound like.', '[{"id": "f0", "type": "textarea", "label": "A rule I hold for myself (\"I should always...\"):"}, {"id": "f1", "type": "textarea", "label": "Times the rule bent and things were still okay:"}, {"id": "f2", "type": "textarea", "label": "What the rule costs me:"}, {"id": "f3", "type": "textarea", "label": "A kinder, more flexible version:"}]'::jsonb, array['core beliefs', 'CBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('solvable-or-open-ended-worry-sorting-page', 'Solvable or Open-Ended Worry Sorting Page', 'cbt'::resource_kind, 'A sheet for splitting a worry into what can be acted on now and what has to be left alone.', 'Use it to help a client choose action for solvable problems and a different response for open-ended worry.', array['Adults']::text[], '20 minutes', 'Have the client write a current worry and ask whether there is a step they could take this week. If so, plan it; if not, the work is on letting the thought pass. Revisit the page next session and see which column filled up.', '[{"id": "f0", "type": "textarea", "label": "A worry on my mind today:"}, {"id": "f1", "type": "textarea", "label": "Is there a step I can take this week? What is it?"}, {"id": "f2", "type": "textarea", "label": "If not, what will I do when the worry shows up?"}, {"id": "f3", "type": "textarea", "label": "How I will know I did my part:"}]'::jsonb, array['worry', 'problem solving']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('behavioral-test-planner-for-predictions', 'Behavioral Test Planner for Predictions', 'cbt'::resource_kind, 'A planner for turning a feared prediction into a small test with a before and after rating.', 'Use it to help a client check a prediction by trying something rather than only thinking about it.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a prediction the client can test within a week and keep the test small. Record the confidence rating before and after so the result is visible. Whatever happens, ask what they learned about the prediction.', '[{"id": "f0", "type": "textarea", "label": "What I predict will happen (and how sure I am, 0 to 100):"}, {"id": "f1", "type": "textarea", "label": "The small test I will try:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "How sure I am of the prediction now:"}]'::jsonb, array['behavioral experiment', 'predictions']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-worksheet', 'Passengers on the Bus Worksheet', 'act'::resource_kind, 'An ACT worksheet using the bus metaphor to name difficult thoughts as passengers while the client keeps driving.', 'Use it to help a client carry hard thoughts without letting them steer.', array['Adults', 'Teens']::text[], '25 minutes', 'Introduce the bus metaphor in session, then let the client name the loud passengers. The key move is that the passengers can talk while the client still picks the route. Ask what direction they would drive if the passengers were quiet.', '[{"id": "f0", "type": "textarea", "label": "The direction I want to drive my life:"}, {"id": "f1", "type": "textarea", "label": "The passengers who shout at me (thoughts and feelings):"}, {"id": "f2", "type": "textarea", "label": "What they tell me to do instead:"}, {"id": "f3", "type": "textarea", "label": "One turn I can make while they are still on board:"}]'::jsonb, array['ACT', 'metaphor', 'values']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-practice-sheet', 'Hands as Thoughts Practice Sheet', 'act'::resource_kind, 'A short exercise using the hands to show how holding a thought tightly differs from holding it loosely.', 'Use it to help a client feel the difference between fusion and distance.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client press their palms over their face, then lower them to their lap, and notice what changes. It lands better as an experience than as an explanation. Ask which thought they want to hold more loosely this week.', '[{"id": "f0", "type": "textarea", "label": "A thought I tend to hold tightly:"}, {"id": "f1", "type": "textarea", "label": "What it felt like with hands over my face:"}, {"id": "f2", "type": "textarea", "label": "What it felt like with hands in my lap:"}, {"id": "f3", "type": "textarea", "label": "How I will remind myself to hold it loosely:"}]'::jsonb, array['defusion', 'ACT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('values-compass-check-in-sheet', 'Values Compass Check-In Sheet', 'act'::resource_kind, 'A weekly sheet for choosing a value and rating how closely the week''s actions pointed toward it.', 'Use it to help a client check their direction rather than their performance.', array['Adults']::text[], 'Weekly, 15 minutes', 'Pick one value the client named earlier and look at the last seven days. Ratings are about direction, so a low number is information and not failure. Pick one small action that would point them closer.', '[{"id": "f0", "type": "textarea", "label": "The value I chose to check:"}, {"id": "f1", "type": "textarea", "label": "How closely my week pointed toward it (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "One moment that moved me toward it:"}, {"id": "f3", "type": "textarea", "label": "One small action for the coming week:"}]'::jsonb, array['values', 'committed action']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('zero-to-ten-willingness-dial-page', 'Zero to Ten Willingness Dial Page', 'act'::resource_kind, 'A dial from 0 to 10 for rating willingness to feel something uncomfortable in service of something that matters.', 'Use it to help a client choose how much discomfort they will carry for a goal.', array['Adults']::text[], '20 minutes', 'Name a valued step that stirs up discomfort and let the client set the dial. Do not push it up; ask what would raise it by one point. Smaller steps often make willingness possible.', '[{"id": "f0", "type": "textarea", "label": "A step that matters to me:"}, {"id": "f1", "type": "textarea", "label": "The discomfort that comes with it:"}, {"id": "f2", "type": "textarea", "label": "My willingness today (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What would move it up by one point:"}]'::jsonb, array['willingness', 'ACT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('observer-self-journal-page', 'Observer Self Journal Page', 'act'::resource_kind, 'A journal page for describing a hard moment from the point of view of the part of the client that notices.', 'Use it to help a client build a steadier stance toward changing thoughts and feelings.', array['Adults']::text[], '20 minutes', 'Read the prompts slowly and ask the client to write as though describing the weather from a hilltop. The sense of a noticing self often comes through in how they word it. Ask what is true of them across good and bad days.', '[{"id": "f0", "type": "textarea", "label": "What I noticed in my mind today:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body today:"}, {"id": "f2", "type": "textarea", "label": "What stays the same about me whatever I notice:"}, {"id": "f3", "type": "textarea", "label": "How noticing changed the moment:"}]'::jsonb, array['self-as-context', 'mindfulness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('four-box-urge-decision-page', 'Four-Box Urge Decision Page', 'dbt'::resource_kind, 'A DBT sheet for weighing short-term and long-term pros and cons of acting or not acting on an urge.', 'Use it to help a client slow down and look at both sides before choosing.', array['Adults', 'Teens']::text[], '20 minutes', 'Fill it in when the client is calm and then again in a harder moment. Four boxes matter: acting now, resisting now, and the long-term side of each. It is a decision aid, so leave the choice to them.', '[{"id": "f0", "type": "textarea", "label": "The urge or choice I am facing:"}, {"id": "f1", "type": "textarea", "label": "Pros and cons of acting on it:"}, {"id": "f2", "type": "textarea", "label": "Pros and cons of not acting on it:"}, {"id": "f3", "type": "textarea", "label": "What I decided and why:"}]'::jsonb, array['distress tolerance', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('check-the-facts-emotion-sheet', 'Check the Facts Emotion Sheet', 'dbt'::resource_kind, 'A DBT sheet for checking whether the facts fit an emotion and how strongly it fits.', 'Use it to help a client test whether the size of a feeling matches the situation.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through the prompting events, the interpretations and whether the feeling and its intensity fit the facts. If it fits, move to problem solving; if not, practice acting opposite. Keep curiosity about the interpretation.', '[{"id": "f0", "type": "textarea", "label": "What happened (just the facts):"}, {"id": "f1", "type": "textarea", "label": "What I told myself it meant:"}, {"id": "f2", "type": "textarea", "label": "The emotion and how strong it is (0 to 100):"}, {"id": "f3", "type": "textarea", "label": "Do the facts fit that emotion and that strength?"}]'::jsonb, array['emotion regulation', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('give-skills-conversation-rehearsal-card', 'GIVE Skills Conversation Rehearsal Card', 'dbt'::resource_kind, 'A card for rehearsing the GIVE skills of being gentle, interested, validating and easy in a conversation.', 'Use it to help a client keep a relationship warm while asking for something.', array['Adults', 'Teens']::text[], '20 minutes', 'Role play a mild conversation using each GIVE step in turn. Clients often rush past the gentle and easy parts, so slow them down. Debrief how it felt to hold back a sharp word.', '[{"id": "f0", "type": "textarea", "label": "The conversation I want to have:"}, {"id": "f1", "type": "textarea", "label": "How I will be gentle:"}, {"id": "f2", "type": "textarea", "label": "How I will show interest and validate:"}, {"id": "f3", "type": "textarea", "label": "What a relaxed, easy manner looks like for me:"}]'::jsonb, array['interpersonal effectiveness', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('wave-of-emotion-surfing-log', 'Wave of Emotion Surfing Log', 'dbt'::resource_kind, 'A short log for riding out an emotion as a wave and noting when it peaks and falls.', 'Use it to help a client see that an emotion rises, peaks and passes without acting on it.', array['Adults']::text[], 'Five minutes per episode', 'Practice in session with a mild feeling first. Have the client rate intensity every minute or so and notice the shape. Review the logs for how long the peaks lasted; clients are often surprised.', '[{"id": "f0", "type": "textarea", "label": "The emotion and what set it off:"}, {"id": "f1", "type": "textarea", "label": "Intensity at the start (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I did while it rose:"}, {"id": "f3", "type": "textarea", "label": "Intensity after ten minutes:"}]'::jsonb, array['regulation', 'mindfulness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('tipp-skills-menu-card', 'TIPP Skills Menu Card', 'dbt'::resource_kind, 'A menu card with the TIPP skills of temperature, intense exercise, paced breathing and paired muscle relaxation.', 'Use it to help a client pick a fast body-based skill when distress runs high.', array['Adults', 'Teens']::text[], '20 minutes', 'Try each skill in session so the client knows what suits them. Ask about any health concern before suggesting exercise or cold exposure, and leave the decision to the client and their own care team. Keep a favorite on the card.', '[{"id": "f0", "type": "textarea", "label": "A moment when my distress felt too high:"}, {"id": "f1", "type": "textarea", "label": "The TIPP skill I will try first:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body after trying it:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this card:"}]'::jsonb, array['distress tolerance', 'skills']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('weekly-appreciation-swap-page', 'Weekly Appreciation Swap Page', 'couples'::resource_kind, 'A page where each partner writes appreciations for the other and reads them aloud.', 'Use it to help partners practice noticing and saying what they value in each other.', array['Couples']::text[], '20 minutes', 'Each partner writes three specific appreciations privately, then reads them aloud while the other listens without deflecting. Watch for the urge to answer with a complaint. Ask each what it was like to be thanked.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three things I appreciated this week:"}, {"id": "f1", "type": "textarea", "label": "Partner B: three things I appreciated this week:"}, {"id": "f2", "type": "textarea", "label": "What it felt like to hear mine read aloud:"}, {"id": "f3", "type": "textarea", "label": "One thing we will keep doing:"}]'::jsonb, array['couples', 'appreciation']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('stress-reducing-conversation-planner', 'Stress-Reducing Conversation Planner', 'couples'::resource_kind, 'A planner for a short talk where one partner shares stress and the other listens without fixing.', 'Use it to help partners support each other about stress from outside the relationship.', array['Couples']::text[], '30 minutes', 'Set a time limit of about fifteen minutes each. The listener asks questions and shows understanding rather than giving advice. Debrief what helped, then switch roles.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the stress I want to share (not about us):"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I will show I am listening:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the stress I want to share:"}, {"id": "f3", "type": "textarea", "label": "Partner A: how I will show I am listening:"}]'::jsonb, array['couples', 'Gottman', 'support']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('dividing-the-household-load-sheet', 'Dividing the Household Load Sheet', 'couples'::resource_kind, 'A sheet where partners list household and family tasks and talk through who carries what.', 'Use it to help partners see the unseen work in a home and share it more fairly.', array['Couples']::text[], '40 minutes', 'Have each partner list every task they can think of, including planning and remembering. Compare lists with curiosity. Name the tasks that fell to one person by default and pick two to move.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I carry, including the unseen ones:"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I carry, including the unseen ones:"}, {"id": "f2", "type": "textarea", "label": "Tasks that fell to one of us by default:"}, {"id": "f3", "type": "textarea", "label": "Two tasks we will move and how we will check in:"}]'::jsonb, array['couples', 'planning', 'fairness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('daily-connection-rituals-picker', 'Daily Connection Rituals Picker', 'couples'::resource_kind, 'A menu of small daily and weekly rituals partners can pick from to stay connected.', 'Use it to help partners build a few dependable moments of closeness.', array['Couples']::text[], '30 minutes', 'Offer examples such as a six-second kiss or a Friday walk, then let the couple write their own. Choose two they both feel good about, not the most ambitious. Revisit in two weeks and change what did not fit.', '[{"id": "f0", "type": "textarea", "label": "Partner A: small rituals I would enjoy:"}, {"id": "f1", "type": "textarea", "label": "Partner B: small rituals I would enjoy:"}, {"id": "f2", "type": "textarea", "label": "The two we both chose:"}, {"id": "f3", "type": "textarea", "label": "When and where we will try them:"}]'::jsonb, array['couples', 'connection', 'routines']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('soft-start-up-rewrite-page', 'Soft Start-Up Rewrite Page', 'couples'::resource_kind, 'A page where partners turn a harsh opening into a gentle one that states a feeling and a request.', 'Use it to help partners raise a concern without starting a fight.', array['Couples']::text[], '25 minutes', 'Have each partner write a recent harsh opening and rewrite it using "I feel... about... I need...". Read the rewrites aloud and give feedback on tone. Keep the examples mild at first.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a harsh way I opened a topic:"}, {"id": "f1", "type": "textarea", "label": "Partner A: my soft start-up version:"}, {"id": "f2", "type": "textarea", "label": "Partner B: a harsh way I opened a topic:"}, {"id": "f3", "type": "textarea", "label": "Partner B: my soft start-up version:"}]'::jsonb, array['couples', 'communication', 'Gottman']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('feelings-treasure-map-craft', 'Feelings Treasure Map Craft', 'kids'::resource_kind, 'Children draw a treasure map where each place on it is a feeling and the treasure is a calming idea.', 'Use it to give a child a playful way to name feelings and plan what helps.', array['Children']::text[], '30 minutes', 'Offer paper, crayons and a few stickers and let the child lay out the map. Each stop is a feeling, and the treasure chest holds something that helps. The parent joins in, asks about each stop with interest, and keeps the map where it can be found.', '[{"id": "f0", "type": "textarea", "label": "Draw the island and the places where feelings live:"}, {"id": "f1", "type": "textarea", "label": "Which feeling is on the biggest part of the map?"}, {"id": "f2", "type": "textarea", "label": "What is in your treasure chest that helps?"}, {"id": "f3", "type": "textarea", "label": "What did your parent notice or learn from the map?"}]'::jsonb, array['kids', 'art', 'emotion identification']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('calm-down-jar-making-session', 'Calm Down Jar Making Session', 'kids'::resource_kind, 'Children make a glitter jar to watch while the glitter settles and they feel calmer.', 'Use it to give a child a hands-on tool for slowing down when upset.', array['Children']::text[], '30 minutes', 'Build the jar together with a clear jar, warm water, glitter glue and a little glitter. Explain that the glitter is like busy thoughts that settle when we stop shaking. The parent practices with the child at home during calm times first and never uses it as a punishment.', '[{"id": "f0", "type": "textarea", "label": "Draw your jar and the colors you picked:"}, {"id": "f1", "type": "textarea", "label": "What makes you feel shaken up like the glitter?"}, {"id": "f2", "type": "textarea", "label": "How do you feel while watching it settle?"}, {"id": "f3", "type": "textarea", "label": "When will you and your parent try the jar?"}]'::jsonb, array['kids', 'craft', 'regulation']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('strengths-cape-decorating-craft', 'Strengths Cape Decorating Craft', 'kids'::resource_kind, 'Children decorate a paper cape with their own strengths and name a superpower for hard moments.', 'Use it to help a child notice and name what they are good at.', array['Children']::text[], '35 minutes', 'Let the child decorate a paper cape or a drawing of one. Ask for strengths from their own point of view first, then let the parent add one or two they have seen. The parent also says what they will do to notice these strengths at home.', '[{"id": "f0", "type": "textarea", "label": "Draw your superhero self:"}, {"id": "f1", "type": "textarea", "label": "Three things I am good at:"}, {"id": "f2", "type": "textarea", "label": "My superpower for a hard moment:"}, {"id": "f3", "type": "textarea", "label": "What my parent sees in me that I like:"}]'::jsonb, array['kids', 'strengths', 'self-esteem']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('worry-monster-feeding-box-craft', 'Worry Monster Feeding Box Craft', 'kids'::resource_kind, 'Children decorate a box as a friendly monster and "feed" it written or drawn worries.', 'Use it to give a child a safe, playful place to put worries and let them go for a while.', array['Children']::text[], '30 minutes', 'The child decorates a box with a mouth slot and gives the monster a name. Worries are drawn or written and dropped in, then the parent and child open the box at a set time. The parent listens, stays calm and does not argue with worries.', '[{"id": "f0", "type": "textarea", "label": "Draw your worry monster:"}, {"id": "f1", "type": "textarea", "label": "A worry I can feed to the monster:"}, {"id": "f2", "type": "textarea", "label": "How did I feel after feeding it?"}, {"id": "f3", "type": "textarea", "label": "What my parent and I will do when we open the box:"}]'::jsonb, array['kids', 'worry', 'externalizing']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('kindness-ripples-drawing-activity', 'Kindness Ripples Drawing Activity', 'kids'::resource_kind, 'Children draw ripples in a pond and fill each ring with acts of kindness for themselves and others.', 'Use it to help a child connect kind actions with feeling good about themselves.', array['Children']::text[], '25 minutes', 'Draw a pond with three rings: kindness to me, to my family and to friends. Ask the child for one idea per ring and pick one to try this week. The parent chooses one kind act to do alongside the child.', '[{"id": "f0", "type": "textarea", "label": "Draw the pond and the three rings:"}, {"id": "f1", "type": "textarea", "label": "A kind thing I can do for myself:"}, {"id": "f2", "type": "textarea", "label": "A kind thing I can do for my family or a friend:"}, {"id": "f3", "type": "textarea", "label": "The one I will try this week, and who will help me:"}]'::jsonb, array['kids', 'gratitude', 'connection']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('feeling-charades-turn-game', 'Feeling Charades Turn Game', 'game'::resource_kind, 'Players take turns acting out a feeling while others guess and share when they have felt it.', 'Use it to help a group practice recognizing and talking about emotions.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Prepare cards with feelings. One player acts without words, others guess, and the actor says when they last felt it. Rotate turns, keep it light and debrief which feelings were hardest to show or guess.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted out and how the others guessed:"}, {"id": "f1", "type": "textarea", "label": "A time I felt that feeling:"}, {"id": "f2", "type": "textarea", "label": "The feeling that was hardest to show:"}, {"id": "f3", "type": "textarea", "label": "What I learned about how feelings look:"}]'::jsonb, array['game', 'emotion identification', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('skill-card-draw-and-rehearse-game', 'Skill Card Draw and Rehearse Game', 'game'::resource_kind, 'Players draw a skill card, name a moment to use it, and practice it aloud for a point.', 'Use it to help a group rehearse coping skills in a low-pressure way.', array['Teens', 'Groups']::text[], '30 minutes', 'Write one coping skill on each card. A player draws, describes a moment they might use it and demonstrates it briefly. The group gives a point for effort. Debrief which skills players want to try this week.', '[{"id": "f0", "type": "textarea", "label": "The skill I drew and when I might use it:"}, {"id": "f1", "type": "textarea", "label": "How it felt to practice it out loud:"}, {"id": "f2", "type": "textarea", "label": "A skill someone else drew that I liked:"}, {"id": "f3", "type": "textarea", "label": "The skill I will try this week:"}]'::jsonb, array['game', 'coping skills', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('hidden-strength-guessing-game', 'Hidden Strength Guessing Game', 'game'::resource_kind, 'Players share two true facts and one strength, and the group guesses which is the strength.', 'Use it to help a group practice naming strengths in a playful way.', array['Teens', 'Groups']::text[], '20 minutes', 'Each player states two ordinary facts and one real strength in any order. The group guesses the strength, then the player explains it. Watch for players who hide behind jokes and gently invite a sincere line in the debrief.', '[{"id": "f0", "type": "textarea", "label": "My two facts and my strength:"}, {"id": "f1", "type": "textarea", "label": "What it felt like to say a strength out loud:"}, {"id": "f2", "type": "textarea", "label": "A strength someone else shared that I noticed:"}, {"id": "f3", "type": "textarea", "label": "A strength I want to use this week:"}]'::jsonb, array['game', 'strengths', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('pass-the-problem-brainstorm-game', 'Pass the Problem Brainstorm Game', 'game'::resource_kind, 'Players pass a problem card around, and each adds one idea without judging the others.', 'Use it to help a group practice problem solving and flexible thinking.', array['Teens', 'Groups']::text[], '30 minutes', 'Write a mild problem on a card and pass it around. Each player adds one idea, silly or serious, and nobody comments until the end. Then the group picks one idea to try and debriefs what it felt like to have ideas received kindly.', '[{"id": "f0", "type": "textarea", "label": "The problem on my card:"}, {"id": "f1", "type": "textarea", "label": "The idea I added:"}, {"id": "f2", "type": "textarea", "label": "The idea I liked most from the group:"}, {"id": "f3", "type": "textarea", "label": "The one I will try this week:"}]'::jsonb, array['game', 'problem solving', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('calm-breathing-relay-game', 'Calm Breathing Relay Game', 'game'::resource_kind, 'Players pass a ball while taking a slow breath each, and notice how the group slows down together.', 'Use it to help a group experience slowing down together with a simple breathing rhythm.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Sit in a circle and pass a soft ball. The holder takes one slow breath before passing. Do two rounds, then ask what changed in the room. Offer to skip or sit out with no pressure. Children do well with a parent or helper beside them.', '[{"id": "f0", "type": "textarea", "label": "How my body felt before the game:"}, {"id": "f1", "type": "textarea", "label": "How my body felt after the game:"}, {"id": "f2", "type": "textarea", "label": "What it was like to breathe with the group:"}, {"id": "f3", "type": "textarea", "label": "Where I could use slow breathing this week:"}]'::jsonb, array['game', 'breathing', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('present-day-safety-anchors-inventory', 'Present-Day Safety Anchors Inventory', 'worksheet'::resource_kind, 'A sheet for listing places, objects and people that bring a sense of safety in the present.', 'Use it to help a client build a personal list of present-day safety anchors.', array['Adults']::text[], '20 minutes', 'Keep the focus on the here and now: places, textures, people and routines that feel steady. Do not ask about what happened. Let the client pace how much to share, and leave some prompts blank if they wish. Add a favorite anchor to a card they can carry.', '[{"id": "f0", "type": "textarea", "label": "A place where I feel most settled:"}, {"id": "f1", "type": "textarea", "label": "Objects or textures that feel comforting:"}, {"id": "f2", "type": "textarea", "label": "People I feel safer around:"}, {"id": "f3", "type": "textarea", "label": "The anchor I will carry with me this week:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('then-versus-now-cue-sorting-sheet', 'Then Versus Now Cue Sorting Sheet', 'cbt'::resource_kind, 'A CBT sheet for sorting a present-day reminder into what is happening now and what belongs to the past.', 'Use it to help a client tell a reminder from a present-day danger.', array['Adults']::text[], '25 minutes', 'Use a recent, mild reminder rather than the most distressing one, and do not ask for the story behind it. The aim is a calm check of present facts: where I am, who is here, what is safe. Pace gently and stop if the client feels flooded.', '[{"id": "f0", "type": "textarea", "label": "The reminder I noticed (a sound, smell, place):"}, {"id": "f1", "type": "textarea", "label": "What is true right now in this room:"}, {"id": "f2", "type": "textarea", "label": "What my body wants to do:"}, {"id": "f3", "type": "textarea", "label": "A grounding step I can take instead:"}]'::jsonb, array['PTSD and trauma', 'stabilizing', 'grounding', 'core CBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('making-room-for-hard-memories-pacing-sheet', 'Making Room for Hard Memories Pacing Sheet', 'act'::resource_kind, 'An ACT sheet for planning how much contact with difficult feelings the client chooses each day, and how to step back.', 'Use it to help a client set a pace for difficult feelings while still doing what matters.', array['Adults']::text[], '20 minutes', 'Frame this as a choice about pacing, not a task to push through. Let the client decide how much room to give difficult feelings and when to step back. Do not request details of events. Link the pace to a value they want to move toward.', '[{"id": "f0", "type": "textarea", "label": "What matters to me that I want to keep doing:"}, {"id": "f1", "type": "textarea", "label": "How much contact with hard feelings feels manageable today?"}, {"id": "f2", "type": "textarea", "label": "What I will do to step back when it is too much:"}, {"id": "f3", "type": "textarea", "label": "A supportive person I can tell about my pace:"}]'::jsonb, array['PTSD and trauma', 'pacing', 'values', 'stabilizing']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('grounding-with-five-senses-skill-card', 'Grounding With Five Senses Skill Card', 'dbt'::resource_kind, 'A DBT card that walks through noticing five things seen, four felt, three heard, two smelled and one tasted.', 'Use it to help a client come back to the present when reminders pull them away.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice it together in session when the client is calm so it is familiar. Allow the client to open or close their eyes as feels safe. Offer variations, such as naming colors or holding something cold. Suggest it as one of several options, not a fix.', '[{"id": "f0", "type": "textarea", "label": "The reminder or moment when I used the skill:"}, {"id": "f1", "type": "textarea", "label": "Five things I could see:"}, {"id": "f2", "type": "textarea", "label": "Four things I could feel and three I could hear:"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward (0 to 10):"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('anchor-object-show-and-tell-game', 'Anchor Object Show and Tell Game', 'game'::resource_kind, 'Players pick an ordinary object, describe its texture and color, and share why it feels steady.', 'Use it to help a group practice grounding with ordinary objects in a gentle way.', array['Groups']::text[], '25 minutes', 'Bring a basket of everyday objects. Each player chooses one and describes only what they can see and feel, passing if they like. Do not ask about events. Debrief what it was like to attend to something plain and which objects they would carry.', '[{"id": "f0", "type": "textarea", "label": "The object I chose and what I noticed:"}, {"id": "f1", "type": "textarea", "label": "What it felt like to focus on it:"}, {"id": "f2", "type": "textarea", "label": "An object at home I could use the same way:"}, {"id": "f3", "type": "textarea", "label": "What I will try this week:"}]'::jsonb, array['PTSD and trauma', 'game', 'grounding', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('not-knowing-practice-ladder-for-small-doubts', 'Not Knowing Practice Ladder for Small Doubts', 'worksheet'::resource_kind, 'A ladder of small situations with uncertain outcomes, ranked by how uncomfortable each feels.', 'Use it to help a client practice not knowing for a little longer, one step at a time.', array['Adults']::text[], '30 minutes', 'Have the client list small uncertainties, such as not checking a text for an hour, and rank them. Start on a low rung and plan when to try it. Review what happened and what the discomfort did when they stayed with it.', '[{"id": "f0", "type": "textarea", "label": "Small uncertain situations I tend to avoid or fix:"}, {"id": "f1", "type": "textarea", "label": "Rank them from easiest to hardest:"}, {"id": "f2", "type": "textarea", "label": "The first one I will practice and when:"}, {"id": "f3", "type": "textarea", "label": "What I noticed when I stayed with not knowing:"}]'::jsonb, array['anxiety', 'uncertainty', 'exposure', 'worry']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('probability-and-coping-two-column-page', 'Probability and Coping Two-Column Page', 'cbt'::resource_kind, 'A CBT page for rating how likely a feared event is and how the client would cope if it happened.', 'Use it to help a client look at both likelihood and coping, instead of only imagining the worst.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose one specific worry and have the client write the feared outcome. Then explore how likely it is and, separately, what resources they would use if it did occur. Keep it curious, and avoid promising that the worry will not come true.', '[{"id": "f0", "type": "textarea", "label": "The specific outcome I fear:"}, {"id": "f1", "type": "textarea", "label": "How likely I think it is, and why:"}, {"id": "f2", "type": "textarea", "label": "If it did happen, what I would do and who would help:"}, {"id": "f3", "type": "textarea", "label": "What I notice after looking at both:"}]'::jsonb, array['anxiety', 'worry', 'core CBT', 'predictions']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('anxiety-as-a-backseat-driver-worksheet', 'Anxiety as a Backseat Driver Worksheet', 'act'::resource_kind, 'An ACT worksheet that pictures anxiety as a loud backseat driver while the client holds the wheel.', 'Use it to help a client keep moving toward something that matters while anxiety talks.', array['Adults']::text[], '25 minutes', 'Use the image of a backseat driver who is loud but not in charge. Ask what the driver says and what the client does when they listen. Then ask for one trip they want to take with the driver still talking.', '[{"id": "f0", "type": "textarea", "label": "What the backseat driver says to me:"}, {"id": "f1", "type": "textarea", "label": "What I do when I let it steer:"}, {"id": "f2", "type": "textarea", "label": "A trip I want to take even if it keeps talking:"}, {"id": "f3", "type": "textarea", "label": "How I will remind myself who is holding the wheel:"}]'::jsonb, array['anxiety', 'ACT', 'metaphor', 'values']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-senses-menu', 'Self-Soothe With the Senses Menu', 'dbt'::resource_kind, 'A menu for choosing something to see, hear, smell, taste and touch that calms the body in anxious moments.', 'Use it to help a client assemble a personal toolkit for self-soothing.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through each sense and let the client name something that appeals to them. A small kit with a scent, a sound and a texture is easy to carry. Test one in session and ask what difference they notice.', '[{"id": "f0", "type": "textarea", "label": "Something calming to see:"}, {"id": "f1", "type": "textarea", "label": "Something calming to hear or smell:"}, {"id": "f2", "type": "textarea", "label": "Something calming to taste or touch:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep my soothing kit:"}]'::jsonb, array['anxiety', 'self-soothing', 'distress tolerance', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('worry-wizard-spell-book-craft', 'Worry Wizard Spell Book Craft', 'kids'::resource_kind, 'Children make a small book of silly spells that shrink worries and draw the wizard casting them.', 'Use it to give a child a playful way to meet a worry with a brave action.', array['Children']::text[], '35 minutes', 'The child draws a wizard and writes or dictates spells such as "Worry, I see you, now I breathe." Keep the tone silly and warm. The parent reads the book with the child at bedtime and models saying a spell in their own worried moment.', '[{"id": "f0", "type": "textarea", "label": "Draw your wizard:"}, {"id": "f1", "type": "textarea", "label": "A worry I want to shrink:"}, {"id": "f2", "type": "textarea", "label": "A spell I made up for it:"}, {"id": "f3", "type": "textarea", "label": "What my parent and I will do when the worry comes:"}]'::jsonb, array['anxiety', 'kids', 'worry', 'art']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('tiny-step-menu-for-low-energy-days', 'Tiny Step Menu for Low Energy Days', 'worksheet'::resource_kind, 'A menu of very small actions in categories like body, people and tasks to choose from on low energy days.', 'Use it to help a client pick one doable action when energy is low.', array['Adults']::text[], '20 minutes', 'Build the menu together in session using steps that take under five minutes. Make sure at least one is something the client usually enjoys. Ask them to pick one a day and note how it went, without pressure to do more.', '[{"id": "f0", "type": "textarea", "label": "Body steps that take five minutes or less:"}, {"id": "f1", "type": "textarea", "label": "People steps (a text, a wave, a short call):"}, {"id": "f2", "type": "textarea", "label": "Tasks I could finish in five minutes:"}, {"id": "f3", "type": "textarea", "label": "The one I will choose on a hard day:"}]'::jsonb, array['depression', 'behavioral activation', 'energy', 'planning']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('whole-day-wasted-thought-rewrite-sheet', 'Whole Day Wasted Thought Rewrite Sheet', 'cbt'::resource_kind, 'A CBT sheet for catching "the whole day was wasted" thinking and listing what did get done.', 'Use it to help a client see partial progress that low mood tends to hide.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to describe a day they called a failure and then list everything that happened, however small. Rewrite the summary with the full picture. Do not push for a cheerful reading; the aim is a more complete one.', '[{"id": "f0", "type": "textarea", "label": "How I summed up my day:"}, {"id": "f1", "type": "textarea", "label": "Everything that did happen, even small things:"}, {"id": "f2", "type": "textarea", "label": "A more complete way to describe the day:"}, {"id": "f3", "type": "textarea", "label": "What I want to remember about days like this:"}]'::jsonb, array['depression', 'core CBT', 'thinking traps', 'self-talk']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('acting-with-heavy-feelings-values-sheet', 'Acting With Heavy Feelings Values Sheet', 'act'::resource_kind, 'An ACT sheet for choosing one small value-driven action to take even when mood is heavy.', 'Use it to help a client keep contact with what matters while feeling low.', array['Adults']::text[], '25 minutes', 'Start by naming what matters, such as friends or being outdoors, and choose a small action that fits. Do not ask the client to feel better first. Plan when and how, and check in on what happened.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me, even now:"}, {"id": "f1", "type": "textarea", "label": "A very small action that fits it:"}, {"id": "f2", "type": "textarea", "label": "What my mood will say about doing it:"}, {"id": "f3", "type": "textarea", "label": "When I will do it and who could support me:"}]'::jsonb, array['depression', 'values', 'committed action', 'acceptance']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-withdrawing-plan', 'Opposite Action for Withdrawing Plan', 'dbt'::resource_kind, 'A DBT plan for choosing the opposite action when low mood urges the client to isolate.', 'Use it to help a client take a small step toward people when the urge is to pull away.', array['Adults', 'Teens']::text[], '20 minutes', 'Name the urge to withdraw and the emotion behind it, then choose a small opposite action such as a short message. Rehearse it. If the client mentions thoughts of ending their life, address it directly, and share that 988 (call or text) is available any time.', '[{"id": "f0", "type": "textarea", "label": "What my mood is telling me to do:"}, {"id": "f1", "type": "textarea", "label": "The opposite action I could try:"}, {"id": "f2", "type": "textarea", "label": "A person I could reach out to:"}, {"id": "f3", "type": "textarea", "label": "Support I can use any time: 988 (call or text). Who else can I call?"}]'::jsonb, array['depression', 'opposite action', 'core DBT', 'safety']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('supporting-a-partner-on-a-low-day-plan', 'Supporting a Partner on a Low Day Plan', 'couples'::resource_kind, 'Partners write down what helps and what does not when one of them is feeling low, and agree a plan.', 'Use it to help a couple support one partner through low days without blame.', array['Couples']::text[], '35 minutes', 'The partner who has low days says what helps and what makes it worse; the other says what they find hard. Agree on a short signal and a small kind action. Check that the helping partner also has support of their own.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me on a low day:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I find hard, and what I can offer:"}, {"id": "f3", "type": "textarea", "label": "Our signal and what we will do when we use it:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('work-alongside-someone-session-planner', 'Work Alongside Someone Session Planner', 'worksheet'::resource_kind, 'A planner for choosing a task, a body-doubling partner and a time block to get something started.', 'Use it to help a client find company and structure for tasks that are hard to begin.', array['Adults', 'Teens']::text[], '20 minutes', 'Body doubling means working alongside someone, in person or on a call. Have the client choose a task, a person and a short time block, then say what the partner will and will not do. Review what made starting easier.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off:"}, {"id": "f1", "type": "textarea", "label": "Who could keep me company while I work:"}, {"id": "f2", "type": "textarea", "label": "The time block and the first tiny step:"}, {"id": "f3", "type": "textarea", "label": "What helped me stay with it:"}]'::jsonb, array['ADHD', 'task initiation', 'executive function', 'planning']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('time-estimate-reality-check-sheet', 'Time Estimate Reality Check Sheet', 'cbt'::resource_kind, 'A sheet for guessing how long tasks take, timing them, and adjusting future plans.', 'Use it to help a client build more accurate expectations of how long things take.', array['Adults', 'Teens']::text[], 'Three tasks over a week', 'Pick three routine tasks and have the client guess the time, then time themselves. Compare without judgment and adjust the plan with a buffer. Notice thoughts like "this will only take a minute" and look at the evidence.', '[{"id": "f0", "type": "textarea", "label": "Task and my guess of how long it takes:"}, {"id": "f1", "type": "textarea", "label": "How long it actually took:"}, {"id": "f2", "type": "textarea", "label": "What I will add to my plan next time:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about my guesses:"}]'::jsonb, array['ADHD', 'executive function', 'predictions', 'habits']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('doing-what-matters-with-a-busy-mind-sheet', 'Doing What Matters With a Busy Mind Sheet', 'act'::resource_kind, 'An ACT sheet for choosing a valued action and carrying a busy, wandering mind along with it.', 'Use it to help a client act on a value while their attention drifts and jumps.', array['Adults']::text[], '25 minutes', 'Choose a valued task and ask what pulls the client''s attention away. The skill is noticing the drift and returning, not stopping it. Plan a short return cue, like a sticky note, and review how many returns they made.', '[{"id": "f0", "type": "textarea", "label": "A task connected to something I value:"}, {"id": "f1", "type": "textarea", "label": "What pulls my attention away:"}, {"id": "f2", "type": "textarea", "label": "How I will notice the drift and come back:"}, {"id": "f3", "type": "textarea", "label": "How many times I returned, and how it felt:"}]'::jsonb, array['ADHD', 'attention', 'values', 'ACT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('impulse-brake-plan-sheet', 'Impulse Brake Plan Sheet', 'dbt'::resource_kind, 'A DBT sheet for planning a short brake between an impulse to interrupt, buy or blurt and the action.', 'Use it to help a client place a small gap between impulse and action.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose one impulse pattern, such as interrupting or impulse buying. Have the client pick a brake, like counting to five or writing it on a list for tomorrow. Rehearse in session and review what they did.', '[{"id": "f0", "type": "textarea", "label": "The impulse I want to slow down:"}, {"id": "f1", "type": "textarea", "label": "My brake (count, breath, wait a day):"}, {"id": "f2", "type": "textarea", "label": "Where I will put a reminder:"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it:"}]'::jsonb, array['ADHD', 'regulation', 'habits', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('beat-the-timer-task-sprint-game', 'Beat the Timer Task Sprint Game', 'game'::resource_kind, 'Players choose a task, set a short timer and race a friendly goal, then rest and share what they did.', 'Use it to help a group try short bursts of work with a built-in break.', array['Teens', 'Groups']::text[], '25 minutes', 'Each player picks a small task, sets a ten-minute timer and works while the others do the same. Rest for two minutes, then share what they did. The point is trying a sprint and a break, not comparing amounts.', '[{"id": "f0", "type": "textarea", "label": "The task I picked and my goal for the sprint:"}, {"id": "f1", "type": "textarea", "label": "What I got done:"}, {"id": "f2", "type": "textarea", "label": "What helped or distracted me:"}, {"id": "f3", "type": "textarea", "label": "Whether I will use a sprint again, and for what:"}]'::jsonb, array['ADHD', 'game', 'task initiation', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('urge-surfing-observation-log', 'Urge Surfing Observation Log', 'worksheet'::resource_kind, 'A log for noticing where an urge shows up, how strong it is, and how it changes over time.', 'Use it to help a client watch an urge rise and fall without acting on it.', array['Adults']::text[], 'Five minutes per urge for a week', 'Introduce urges as waves that rise and pass. The client records the cue, the place in the body, strength every few minutes and what they did. Review the logs for how long urges lasted and what helped. Urges are not a failure.', '[{"id": "f0", "type": "textarea", "label": "What set off the urge (a cue, place, feeling):"}, {"id": "f1", "type": "textarea", "label": "Where I felt it in my body:"}, {"id": "f2", "type": "textarea", "label": "Strength at the start and after ten minutes (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What I did while it passed:"}]'::jsonb, array['addiction', 'substance use', 'urges', 'mindfulness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('triggers-and-alternatives-chain-sheet', 'Triggers and Alternatives Chain Sheet', 'cbt'::resource_kind, 'A CBT chain linking a trigger, thought, urge and action, with an alternative at each link.', 'Use it to help a client find places in a familiar chain where a different choice is possible.', array['Adults']::text[], '30 minutes', 'Walk through a recent time when an urge showed up. Name the trigger, thought, feeling, urge and action, and add one alternative at each link. Keep the tone curious and avoid shame.', '[{"id": "f0", "type": "textarea", "label": "The trigger:"}, {"id": "f1", "type": "textarea", "label": "The thought and the feeling that followed:"}, {"id": "f2", "type": "textarea", "label": "The urge and what I did:"}, {"id": "f3", "type": "textarea", "label": "An alternative I could try at one of the links:"}]'::jsonb, array['addiction', 'substance use', 'triggers', 'relapse prevention']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('values-beyond-substance-use-sheet', 'Values Beyond Substance Use Sheet', 'act'::resource_kind, 'An ACT sheet for naming what matters in life and what substance use has made harder.', 'Use it to help a client connect changes in substance use to what they care about.', array['Adults']::text[], '25 minutes', 'Let the client lead with what matters in relationships, work and health. Then ask, without judgment, how substance use fits with those values. Choose one small action that points toward a value this week.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me in my relationships and health:"}, {"id": "f1", "type": "textarea", "label": "How substance use has helped, and what it has cost:"}, {"id": "f2", "type": "textarea", "label": "A small action that points toward what matters:"}, {"id": "f3", "type": "textarea", "label": "Who can support me with it:"}]'::jsonb, array['addiction', 'substance use', 'values', 'committed action']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('urge-distraction-and-comfort-menu', 'Urge Distraction and Comfort Menu', 'dbt'::resource_kind, 'A DBT menu of activities that distract, soothe or engage for use when an urge strikes.', 'Use it to help a client have ready options in a moment when an urge is strong.', array['Adults']::text[], '20 minutes', 'Build the menu together, using the ACCEPTS idea of activities, contributing, comparisons, emotions, pushing away, thoughts and sensations. Ask which ones are realistic at 10 p.m. Keep the card visible and review what was used.', '[{"id": "f0", "type": "textarea", "label": "Activities that take my mind elsewhere:"}, {"id": "f1", "type": "textarea", "label": "Ways to comfort myself that do not involve substances:"}, {"id": "f2", "type": "textarea", "label": "A person I can contact when an urge is strong:"}, {"id": "f3", "type": "textarea", "label": "The first thing on my menu I will try:"}]'::jsonb, array['addiction', 'substance use', 'urges', 'distress tolerance']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('partner-support-agreement-for-recovery-journeys', 'Partner Support Agreement for Recovery Journeys', 'couples'::resource_kind, 'Partners write down how the one making changes would like support and what the other needs.', 'Use it to help partners agree on helpful support around changes in substance use.', array['Couples']::text[], '40 minutes', 'Each partner says what kind of support is useful and what feels controlling or unhelpful. Agree on how to check in and what to do after a slip. Make sure the supporting partner has people and time of their own.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what support helps me, and what does not:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer and what I need:"}, {"id": "f2", "type": "textarea", "label": "How we will check in and how often:"}, {"id": "f3", "type": "textarea", "label": "What we will do if there is a setback:"}]'::jsonb, array['addiction', 'couples', 'substance use', 'support']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('early-anger-signals-body-check-sheet', 'Early Anger Signals Body Check Sheet', 'worksheet'::resource_kind, 'A sheet for noticing early body signals that anger is building before it peaks.', 'Use it to help a client catch anger earlier, when there is more choice.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client recall a recent angry moment and trace what showed up in the body first: jaw, hands, heat. Rate each from 1 to 10 and mark a point where they could still pause. Practice naming the signal aloud.', '[{"id": "f0", "type": "textarea", "label": "A recent time I felt angry:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body first:"}, {"id": "f2", "type": "textarea", "label": "At what number could I still pause (1 to 10)?"}, {"id": "f3", "type": "textarea", "label": "What I will do when I notice that signal:"}]'::jsonb, array['anger management', 'anger', 'body awareness', 'de-escalation']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('angry-thoughts-fairness-check-sheet', 'Angry Thoughts Fairness Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for checking the "that is not fair" and "they did it on purpose" thoughts behind anger.', 'Use it to help a client test the thoughts that feed anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a recent event and write the angry thought. Look for other explanations and for the rule the client feels was broken. Do not argue the anger away; work toward a thought that still respects their feelings and leaves room for choice.', '[{"id": "f0", "type": "textarea", "label": "What happened and what I thought:"}, {"id": "f1", "type": "textarea", "label": "The rule I felt was broken:"}, {"id": "f2", "type": "textarea", "label": "Other explanations that could be true:"}, {"id": "f3", "type": "textarea", "label": "A thought that is fair to me and to the other person:"}]'::jsonb, array['anger management', 'anger', 'thinking traps', 'fairness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('anger-and-what-it-protects-worksheet', 'Anger and What It Protects Worksheet', 'act'::resource_kind, 'An ACT worksheet for asking what the anger is protecting and what action fits that value.', 'Use it to help a client look beneath anger to what matters and act on it.', array['Adults']::text[], '25 minutes', 'Treat anger as a signal that something valued is at stake. Ask what it protects, such as respect or fairness. Then choose an action that serves the value more effectively than a lash-out.', '[{"id": "f0", "type": "textarea", "label": "A recent time I was angry:"}, {"id": "f1", "type": "textarea", "label": "What mattered to me in that moment:"}, {"id": "f2", "type": "textarea", "label": "What I did, and whether it helped what mattered:"}, {"id": "f3", "type": "textarea", "label": "A different action that fits that value:"}]'::jsonb, array['anger management', 'anger', 'values', 'workability']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('cool-down-skills-ladder-for-hot-moments', 'Cool Down Skills Ladder for Hot Moments', 'dbt'::resource_kind, 'A ladder of DBT skills from quick body steps to talking it through, for use as anger rises.', 'Use it to help a client choose a skill that fits how hot the moment is.', array['Adults', 'Teens']::text[], '25 minutes', 'Rate anger from 1 to 10 and match skills to levels: paced breathing and cold water at high levels, walking at middle levels, talking it through at lower levels. Practice a high-level skill in session. Have the client fill in their own ladder.', '[{"id": "f0", "type": "textarea", "label": "Skills for when I am at 8 to 10:"}, {"id": "f1", "type": "textarea", "label": "Skills for when I am at 5 to 7:"}, {"id": "f2", "type": "textarea", "label": "Skills for when I am at 1 to 4:"}, {"id": "f3", "type": "textarea", "label": "The one I will practice this week:"}]'::jsonb, array['anger management', 'anger', 'distress tolerance', 'skills']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('paper-volcano-pressure-gauge-craft', 'Paper Volcano Pressure Gauge Craft', 'kids'::resource_kind, 'Children build a paper volcano with a gauge and place a marker for how hot they feel, with ways to let steam out safely.', 'Use it to give a child a visual way to notice anger building and choose a calming action.', array['Children']::text[], '35 minutes', 'The child draws or builds a volcano with zones and a movable arrow, then lists safe ways to let off steam. The parent practices one with the child, uses the gauge during calm times and responds without punishing the anger.', '[{"id": "f0", "type": "textarea", "label": "Draw your volcano and mark where you are today:"}, {"id": "f1", "type": "textarea", "label": "How my body feels when the volcano is almost ready:"}, {"id": "f2", "type": "textarea", "label": "Safe ways I can let steam out:"}, {"id": "f3", "type": "textarea", "label": "What my parent will do when I show a high number:"}]'::jsonb, array['anger management', 'kids', 'anger', 'art']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('reassurance-seeking-tally-sheet', 'Reassurance Seeking Tally Sheet', 'worksheet'::resource_kind, 'A tally for counting how often reassurance is sought or checks are made, and what happens in between.', 'Use it to help a client see how often reassurance and checking happen, and how long relief lasts.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to tally each time they check or ask for reassurance and note how long relief lasted. The aim is a clear picture, not an instant cut. Look at the pattern together and choose one small delay to practice.', '[{"id": "f0", "type": "textarea", "label": "What I checked or asked about:"}, {"id": "f1", "type": "textarea", "label": "How anxious I felt before (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "How long relief lasted:"}, {"id": "f3", "type": "textarea", "label": "One small delay I could try next time:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'monitoring', 'exposure']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('thought-is-not-fact-sorting-sheet', 'Thought Is Not Fact Sorting Sheet', 'cbt'::resource_kind, 'A CBT sheet for sorting intrusive thoughts from plans and noticing what the mind does with them.', 'Use it to help a client see that having a thought is different from wanting or doing it.', array['Adults']::text[], '25 minutes', 'Normalize that many people have odd intrusive thoughts. Have the client write one and explore what meaning they attach to it. Practice treating it as a passing mental event. Avoid giving reassurance that the thought will not come true.', '[{"id": "f0", "type": "textarea", "label": "An unwanted thought that shows up:"}, {"id": "f1", "type": "textarea", "label": "What I think it says about me:"}, {"id": "f2", "type": "textarea", "label": "What I do in response (check, push away, argue):"}, {"id": "f3", "type": "textarea", "label": "How I could let it be there without acting:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'core CBT', 'core beliefs']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('letting-the-thought-be-there-willingness-page', 'Letting the Thought Be There Willingness Page', 'act'::resource_kind, 'An ACT page for practicing allowing an unwanted thought to stay while doing something that matters.', 'Use it to help a client carry an intrusive thought during a valued activity.', array['Adults']::text[], '25 minutes', 'Choose an activity the client values and a thought that tends to interrupt it. Practice letting the thought ride along rather than solving it. Review whether time spent with the thought changed how much it took over.', '[{"id": "f0", "type": "textarea", "label": "An activity I value that the thought interrupts:"}, {"id": "f1", "type": "textarea", "label": "The thought that shows up:"}, {"id": "f2", "type": "textarea", "label": "How I will let it come along:"}, {"id": "f3", "type": "textarea", "label": "What happened in the activity:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'willingness', 'ACT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('wait-it-out-ritual-delay-timer-plan', 'Wait It Out Ritual Delay Timer Plan', 'dbt'::resource_kind, 'A DBT plan for delaying a ritual by a short, chosen amount of time and riding the discomfort.', 'Use it to help a client build the ability to wait before acting on an urge to do a ritual.', array['Adults']::text[], '20 minutes', 'Choose one ritual and a very short delay, such as two minutes. Plan what they will do during the wait, like paced breathing or noticing. Increase the delay a little each week. Review what the discomfort did.', '[{"id": "f0", "type": "textarea", "label": "The ritual I want to delay:"}, {"id": "f1", "type": "textarea", "label": "How long I will wait this week:"}, {"id": "f2", "type": "textarea", "label": "What I will do while waiting:"}, {"id": "f3", "type": "textarea", "label": "What I noticed as the wait went on:"}]'::jsonb, array['OCD', 'urges', 'distress tolerance', 'exposure']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('ocd-bully-bossing-back-drawing-page', 'OCD Bully Bossing Back Drawing Page', 'kids'::resource_kind, 'Children draw the "worry bully" that gives bossy orders and write a reply that bosses it back.', 'Use it to help a child separate themselves from bossy worry thoughts in a playful way.', array['Children']::text[], '30 minutes', 'Invite the child to draw the bully and give it a silly name. List what it bosses them to do and practice talking back. The parent learns to stay calm, avoid giving extra reassurance, and cheer on any small attempt.', '[{"id": "f0", "type": "textarea", "label": "Draw and name your worry bully:"}, {"id": "f1", "type": "textarea", "label": "What it bosses me to do:"}, {"id": "f2", "type": "textarea", "label": "What I say back to it:"}, {"id": "f3", "type": "textarea", "label": "How my parent can help me without giving in to the bully:"}]'::jsonb, array['OCD', 'kids', 'externalizing', 'art']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('panic-sensations-body-map', 'Panic Sensations Body Map', 'worksheet'::resource_kind, 'A body map where a client marks where they feel panic sensations and what they fear each one means.', 'Use it to help a client see the sensations and the fears attached to them side by side.', array['Adults', 'Teens']::text[], '25 minutes', 'Provide a body outline and ask the client to mark where sensations appear. Beside each, write the fear it brings. Rule out medical concerns through their own healthcare provider as needed. Use it to start work on how sensations are interpreted.', '[{"id": "f0", "type": "textarea", "label": "Where I feel sensations during panic (mark the map):"}, {"id": "f1", "type": "textarea", "label": "What each sensation makes me think is happening:"}, {"id": "f2", "type": "textarea", "label": "What helps when it rises:"}, {"id": "f3", "type": "textarea", "label": "What I learned from filling it out:"}]'::jsonb, array['panic attacks', 'panic', 'body awareness', 'psychoeducation']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('panic-peak-and-pass-prediction-log', 'Panic Peak and Pass Prediction Log', 'cbt'::resource_kind, 'A CBT log for predicting what will happen during panic and comparing it with what happened.', 'Use it to help a client test the predictions that fuel fear of panic.', array['Adults']::text[], 'One week', 'After each episode, the client writes what they feared would happen and what actually happened, including how long the peak lasted. Review the pattern and look for fears that did not come true. Avoid false guarantees.', '[{"id": "f0", "type": "textarea", "label": "What I feared would happen:"}, {"id": "f1", "type": "textarea", "label": "What actually happened:"}, {"id": "f2", "type": "textarea", "label": "How long the peak lasted:"}, {"id": "f3", "type": "textarea", "label": "What I would tell myself next time:"}]'::jsonb, array['panic attacks', 'panic', 'predictions', 'behavioral experiment']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('panic-passengers-making-room-sheet', 'Panic Passengers Making Room Sheet', 'act'::resource_kind, 'An ACT sheet for allowing panic sensations while continuing a valued activity.', 'Use it to help a client keep doing what matters while panic sensations come along.', array['Adults']::text[], '25 minutes', 'Choose a valued activity panic has shrunk and plan a small step back toward it. Practice making room for sensations in session. Review what the client learned about their ability to carry them.', '[{"id": "f0", "type": "textarea", "label": "An activity panic has taken from me:"}, {"id": "f1", "type": "textarea", "label": "The sensations I expect when I go back to it:"}, {"id": "f2", "type": "textarea", "label": "How I will make room for them:"}, {"id": "f3", "type": "textarea", "label": "What I learned from trying:"}]'::jsonb, array['panic attacks', 'panic', 'willingness', 'values']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-cool-water-skill-card', 'Paced Breathing and Cool Water Skill Card', 'dbt'::resource_kind, 'A DBT card for slowing breath with a longer exhale and using cool water on the face.', 'Use it to help a client have two quick body skills for the peak of high arousal.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice a longer exhale than inhale in session, and talk through cool water on the face. Ask about any health issue before suggesting a cold-water skill. Help the client use these as ways to ride the wave, not stop it.', '[{"id": "f0", "type": "textarea", "label": "When I will use the skill:"}, {"id": "f1", "type": "textarea", "label": "What I notice after five slow breaths:"}, {"id": "f2", "type": "textarea", "label": "What cool water does for me:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this card:"}]'::jsonb, array['panic attacks', 'panic', 'breathing', 'distress tolerance']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('wave-rider-rating-game', 'Wave Rider Rating Game', 'game'::resource_kind, 'Players imagine a wave with a number, rate intensity as it rises and falls, and share how they ride it.', 'Use it to help a group see that intensity rises, peaks and passes.', array['Teens', 'Groups']::text[], '25 minutes', 'Draw a wave on a board. Players take turns describing a mild uncomfortable moment, rating it and placing it on the wave, then naming what helped it pass. Keep examples mild and debrief shared findings.', '[{"id": "f0", "type": "textarea", "label": "A mild moment I put on the wave:"}, {"id": "f1", "type": "textarea", "label": "Where it peaked and how I rode it:"}, {"id": "f2", "type": "textarea", "label": "What someone else did that I want to try:"}, {"id": "f3", "type": "textarea", "label": "What the wave taught me:"}]'::jsonb, array['panic attacks', 'game', 'panic', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('family-routine-anchor-chart-planner', 'Family Routine Anchor Chart Planner', 'worksheet'::resource_kind, 'A planner for choosing three or four anchor moments in the day and what each one looks like.', 'Use it to help a parent build predictable moments that steady a household.', array['Adults']::text[], '30 minutes', 'Pick anchor moments like waking, after school, dinner and bedtime. Keep each routine to a few steps. Choose one to start with and check back on what worked and what needs flexing.', '[{"id": "f0", "type": "textarea", "label": "Anchor moments in our day:"}, {"id": "f1", "type": "textarea", "label": "What each one looks like now:"}, {"id": "f2", "type": "textarea", "label": "The first routine I will work on:"}, {"id": "f3", "type": "textarea", "label": "How I will know it is helping:"}]'::jsonb, array['parenting', 'routines', 'planning']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('catching-parent-guilt-thought-sheet', 'Catching Parent Guilt Thought Sheet', 'cbt'::resource_kind, 'A CBT sheet for noticing guilt thoughts like "a good parent would never" and testing them.', 'Use it to help a parent meet guilt with a fairer thought and a realistic next step.', array['Adults']::text[], '20 minutes', 'Name the guilt thought and the standard it assumes. Ask what a kind friend who was also a parent would say. Pick a realistic next step, such as an apology or a repair, rather than self-blame.', '[{"id": "f0", "type": "textarea", "label": "The guilt thought I notice:"}, {"id": "f1", "type": "textarea", "label": "The standard behind it:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend in my position:"}, {"id": "f3", "type": "textarea", "label": "One repair or next step I can take:"}]'::jsonb, array['parenting', 'guilt', 'self-compassion']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('parenting-by-values-not-by-mood-sheet', 'Parenting by Values Not by Mood Sheet', 'act'::resource_kind, 'An ACT sheet for choosing a parenting value and a response that fits it when feeling reactive.', 'Use it to help a parent act on the parent they want to be in a hard moment.', array['Adults']::text[], '25 minutes', 'Ask what kind of parent they want to be and what they do when upset. Look at the gap and choose a response that fits the value. Rehearse the first sentence they might say.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent I want to be:"}, {"id": "f1", "type": "textarea", "label": "What I tend to do when I am upset:"}, {"id": "f2", "type": "textarea", "label": "A response that fits that value:"}, {"id": "f3", "type": "textarea", "label": "The first sentence I will say:"}]'::jsonb, array['parenting', 'values', 'workability']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('validate-then-limit-script-card', 'Validate Then Limit Script Card', 'dbt'::resource_kind, 'A DBT card for a parent to validate a child''s feeling and then hold a limit kindly.', 'Use it to help a parent stay warm and firm in the same sentence.', array['Adults']::text[], '20 minutes', 'Practice a validating line and a limit side by side, such as "I get that you are upset, and screen time is over." Role play a mild example. Ask how it feels to be warm and firm together.', '[{"id": "f0", "type": "textarea", "label": "A moment when my child is upset and I need to hold a limit:"}, {"id": "f1", "type": "textarea", "label": "What I can validate:"}, {"id": "f2", "type": "textarea", "label": "The limit I will hold:"}, {"id": "f3", "type": "textarea", "label": "How I will keep my voice calm:"}]'::jsonb, array['parenting', 'validation', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('co-parenting-agreement-and-check-in-sheet', 'Co-Parenting Agreement and Check-In Sheet', 'couples'::resource_kind, 'Partners agree on a few shared parenting rules, who does what, and a weekly check-in.', 'Use it to help co-parents get on the same page and support each other.', array['Couples']::text[], '40 minutes', 'Choose two or three issues where mixed messages cause trouble. Each partner states what matters to them, then they agree on a shared approach and a time to check in. Notice when one partner steps in and undermines the other.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what matters most to me about this issue:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what matters most to me about this issue:"}, {"id": "f2", "type": "textarea", "label": "The approach we agree on:"}, {"id": "f3", "type": "textarea", "label": "When and how we will check in:"}]'::jsonb, array['parenting', 'couples', 'communication']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('rest-window-and-helper-shift-planner', 'Rest Window and Helper Shift Planner', 'worksheet'::resource_kind, 'A planner for dividing nights and daytime help so a new parent can get protected stretches of rest.', 'Use it to help a new parent plan rest and support in the early months.', array['Adults', 'Couples']::text[], '30 minutes', 'Map a typical 24 hours with the client and mark possible rest windows. List who can help and with what. Name a protected stretch for the parent and agree how to ask. Suggest the client talk to their own healthcare provider about any health concerns.', '[{"id": "f0", "type": "textarea", "label": "Hours when baby usually needs me:"}, {"id": "f1", "type": "textarea", "label": "Who can help and with what:"}, {"id": "f2", "type": "textarea", "label": "A protected rest window I will ask for:"}, {"id": "f3", "type": "textarea", "label": "What I will say to ask for it:"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'support']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('new-parent-should-statements-sheet', 'New Parent Should Statements Sheet', 'cbt'::resource_kind, 'A CBT sheet for spotting "I should be happy" or "I should know what to do" and softening them.', 'Use it to help a new parent be kinder to themselves in a demanding season.', array['Adults']::text[], '20 minutes', 'Listen for shoulds about feelings, feeding, bonding and coping. Write the thought, the pressure behind it and a gentler version. Ask where the standard comes from. Encourage the client to share concerns about mood with their own healthcare provider.', '[{"id": "f0", "type": "textarea", "label": "A should I keep telling myself:"}, {"id": "f1", "type": "textarea", "label": "Where that pressure comes from:"}, {"id": "f2", "type": "textarea", "label": "A gentler way to say it:"}, {"id": "f3", "type": "textarea", "label": "What would help me meet that gentler standard:"}]'::jsonb, array['perinatal and postpartum', 'self-compassion', 'thinking traps']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('small-moments-of-meaning-for-new-parents', 'Small Moments of Meaning for New Parents', 'act'::resource_kind, 'An ACT sheet for finding tiny moments that connect to values in days that feel like a blur.', 'Use it to help a new parent notice and plan small value-driven moments.', array['Adults']::text[], '20 minutes', 'Ask what mattered to the client before the baby arrived and what matters now. Find five-minute ways to connect to those values. Keep the list short and forgiving.', '[{"id": "f0", "type": "textarea", "label": "What matters to me now as a parent and as a person:"}, {"id": "f1", "type": "textarea", "label": "A five-minute action that fits:"}, {"id": "f2", "type": "textarea", "label": "What gets in the way:"}, {"id": "f3", "type": "textarea", "label": "When I will try it this week:"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-care']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('weathering-a-hard-night-skill-plan', 'Weathering a Hard Night Skill Plan', 'dbt'::resource_kind, 'A DBT plan listing skills to use during a hard overnight or evening stretch with a baby.', 'Use it to help a new parent have a plan for the hardest hours.', array['Adults']::text[], '25 minutes', 'Ask about the hardest times of day and build a menu of skills such as paced breathing, a cold drink, a supportive text or a short mindful moment. If thoughts of harm to self or baby arise, address it right away and share 988 (call or text) and their provider.', '[{"id": "f0", "type": "textarea", "label": "The hardest hours for me:"}, {"id": "f1", "type": "textarea", "label": "Skills I will try during them:"}, {"id": "f2", "type": "textarea", "label": "Someone I can message at those times:"}, {"id": "f3", "type": "textarea", "label": "If things feel unsafe, I can call or text 988. Who else will I call?"}]'::jsonb, array['perinatal and postpartum', 'distress tolerance', 'safety']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('sharing-the-baby-load-check-in-page', 'Sharing the Baby Load Check-In Page', 'couples'::resource_kind, 'Partners talk through how care of the baby and the home is shared and how each is feeling.', 'Use it to help partners keep talking through the load of caring for a baby.', array['Couples']::text[], '30 minutes', 'Each partner shares what the last week was like, what they appreciate and what feels heavy. Then look at the load in the home. Agree on one change and a time to check back.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how the week felt and what I appreciate:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how the week felt and what I appreciate:"}, {"id": "f2", "type": "textarea", "label": "What feels heavy for either of us:"}, {"id": "f3", "type": "textarea", "label": "One change we will try:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'fairness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('inner-critic-interview-sheet', 'Inner Critic Interview Sheet', 'worksheet'::resource_kind, 'A sheet for interviewing the inner critic about what it wants, what it fears and how it helps or hurts.', 'Use it to help a client get to know the critic''s voice instead of obeying it.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to treat the critic as a character with a job. Ask what it is trying to protect and what it costs. Then write a reply from a calmer part of themselves. Do not insist the critic is wrong; look at how helpful it is.', '[{"id": "f0", "type": "textarea", "label": "What my inner critic says most often:"}, {"id": "f1", "type": "textarea", "label": "What it is trying to protect me from:"}, {"id": "f2", "type": "textarea", "label": "What its voice costs me:"}, {"id": "f3", "type": "textarea", "label": "What I would say back with kindness:"}]'::jsonb, array['self-esteem', 'self-criticism', 'self-compassion']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('core-belief-evidence-log-for-worth', 'Core Belief Evidence Log for Worth', 'cbt'::resource_kind, 'A CBT log for collecting evidence for and against a belief about being worth less than others.', 'Use it to help a client build a more balanced view of their own worth.', array['Adults']::text[], 'Two weeks', 'State the belief and rate it. Each day, the client records one piece of evidence that fits a fairer view, however small. Review after two weeks and rerate. Dismissed evidence is common; ask what makes it hard to accept.', '[{"id": "f0", "type": "textarea", "label": "The belief about myself and how strongly I hold it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Evidence today that does not fit the belief:"}, {"id": "f2", "type": "textarea", "label": "What I tend to say to dismiss it:"}, {"id": "f3", "type": "textarea", "label": "A fairer way to describe myself:"}]'::jsonb, array['self-esteem', 'core beliefs', 'evidence']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('conditions-on-my-worth-reflection-page', 'Conditions on My Worth Reflection Page', 'act'::resource_kind, 'An ACT reflection on what the client believes they must achieve to be okay and what a steady sense of worth could look like.', 'Use it to help a client loosen the conditions placed on self-worth.', array['Adults']::text[], '25 minutes', 'Ask for the conditions, such as "I am okay only if I succeed." Look at how living by them has gone. Explore what it would mean to act on values without needing a verdict on worth.', '[{"id": "f0", "type": "textarea", "label": "Conditions I place on feeling okay:"}, {"id": "f1", "type": "textarea", "label": "How living by them has gone:"}, {"id": "f2", "type": "textarea", "label": "A value I can act on without needing proof of worth:"}, {"id": "f3", "type": "textarea", "label": "One action I will try this week:"}]'::jsonb, array['self-esteem', 'values', 'acceptance']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('my-feelings-make-sense-statement-card', 'My Feelings Make Sense Statement Card', 'dbt'::resource_kind, 'A DBT card for practicing validating oneself: feelings make sense given the situation.', 'Use it to help a client treat their own feelings with understanding.', array['Adults', 'Teens']::text[], '20 minutes', 'Introduce self-validation as acknowledging that feelings make sense in context, without agreeing with everything. Write three statements together and read them aloud. Ask what is hard about hearing them.', '[{"id": "f0", "type": "textarea", "label": "A feeling I had this week:"}, {"id": "f1", "type": "textarea", "label": "Why it makes sense, given what was going on:"}, {"id": "f2", "type": "textarea", "label": "My self-validation statement:"}, {"id": "f3", "type": "textarea", "label": "How it felt to say it:"}]'::jsonb, array['self-esteem', 'validation', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('me-poster-of-strengths-and-favorites-craft', 'Me Poster of Strengths and Favorites Craft', 'kids'::resource_kind, 'Children make a poster with drawings of their strengths, favorites and things they are proud of.', 'Use it to help a child see what is special about them in pictures.', array['Children']::text[], '35 minutes', 'Provide paper, markers and stickers. The child fills the poster with things they are good at, love and are proud of. The parent adds one thing they appreciate and hangs the poster where the child can see it.', '[{"id": "f0", "type": "textarea", "label": "Draw yourself in the middle of the poster:"}, {"id": "f1", "type": "textarea", "label": "Three things I am good at:"}, {"id": "f2", "type": "textarea", "label": "Something I am proud of this month:"}, {"id": "f3", "type": "textarea", "label": "What my parent wrote on my poster:"}]'::jsonb, array['self-esteem', 'kids', 'strengths']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('social-spotlight-reality-check-sheet', 'Social Spotlight Reality Check Sheet', 'worksheet'::resource_kind, 'A sheet for comparing how much the client thinks others notice them with what they observed.', 'Use it to help a client test the sense that everyone is watching.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a social moment and have the client rate how much they think others noticed. Then plan a way to observe what others actually did. Compare the two and ask what they learned.', '[{"id": "f0", "type": "textarea", "label": "A social moment where I felt watched:"}, {"id": "f1", "type": "textarea", "label": "How much I think people noticed (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What I actually observed others doing:"}, {"id": "f3", "type": "textarea", "label": "What I learned about the spotlight:"}]'::jsonb, array['social anxiety', 'predictions', 'evidence']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('post-event-replay-rewrite-sheet', 'Post-Event Replay Rewrite Sheet', 'cbt'::resource_kind, 'A CBT sheet for stopping the harsh replay after social events and writing a fairer summary.', 'Use it to help a client replace a harsh post-mortem with a balanced recap.', array['Adults']::text[], '20 minutes', 'After a social event, have the client write the replay as it runs, then list what went okay and what was within their control. Look for mind reading and write a fairer summary. Practice setting a time limit for replaying.', '[{"id": "f0", "type": "textarea", "label": "The replay my mind runs:"}, {"id": "f1", "type": "textarea", "label": "What went okay, even if small:"}, {"id": "f2", "type": "textarea", "label": "What I assumed others thought:"}, {"id": "f3", "type": "textarea", "label": "A fairer summary of the event:"}]'::jsonb, array['social anxiety', 'thinking traps', 'self-talk']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('showing-up-with-nerves-values-sheet', 'Showing Up With Nerves Values Sheet', 'act'::resource_kind, 'An ACT sheet for choosing a social value, like connection or learning, and taking a step with nerves along.', 'Use it to help a client take social steps that matter while nerves come along.', array['Adults']::text[], '25 minutes', 'Ask what connection they want and pick a small step, such as saying hello to one person. Rate willingness and plan to bring the nerves along. Review the step without grading performance.', '[{"id": "f0", "type": "textarea", "label": "A connection or interest that matters to me:"}, {"id": "f1", "type": "textarea", "label": "A small social step toward it:"}, {"id": "f2", "type": "textarea", "label": "The nerves I expect to bring along:"}, {"id": "f3", "type": "textarea", "label": "What I did and what I noticed:"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('fast-skill-self-respect-rehearsal-card', 'FAST Skill Self-Respect Rehearsal Card', 'dbt'::resource_kind, 'A DBT card for rehearsing the FAST skills of being fair, apologizing less, sticking to values and being truthful.', 'Use it to help a client keep their self-respect in social moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Role play a mild situation where the client would normally over-apologize or go along. Practice each FAST step. Debrief how self-respect felt compared with pleasing.', '[{"id": "f0", "type": "textarea", "label": "A social moment where I tend to go along or over-apologize:"}, {"id": "f1", "type": "textarea", "label": "How I can be fair to myself and others:"}, {"id": "f2", "type": "textarea", "label": "A value I want to stick to:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will practice:"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('conversation-opener-practice-card-game', 'Conversation Opener Practice Card Game', 'game'::resource_kind, 'Players draw cards with simple conversation openers and practice them in short exchanges.', 'Use it to help a group practice starting and ending small conversations.', array['Teens', 'Groups']::text[], '30 minutes', 'Prepare cards with mild openers and ways to end a chat. Players pair up, try one and switch. Keep it silly and low-pressure, and let anyone pass. Debrief what felt easier than expected.', '[{"id": "f0", "type": "textarea", "label": "The opener I tried:"}, {"id": "f1", "type": "textarea", "label": "What happened and how I felt:"}, {"id": "f2", "type": "textarea", "label": "An opener from someone else I liked:"}, {"id": "f3", "type": "textarea", "label": "One I will try with a real person this week:"}]'::jsonb, array['social anxiety', 'game', 'social skills', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('waves-of-grief-day-tracker', 'Waves of Grief Day Tracker', 'worksheet'::resource_kind, 'A tracker for noting when grief rises, what set it off and what helped it ease over a week.', 'Use it to help a client see the rhythm of grief and what supports them.', array['Adults']::text[], 'One week', 'Present grief as coming in waves that look different each day. Have the client note time, trigger and what helped. Review together for patterns and for supports they might use more. There is no right timeline.', '[{"id": "f0", "type": "textarea", "label": "When grief came up today:"}, {"id": "f1", "type": "textarea", "label": "What set it off:"}, {"id": "f2", "type": "textarea", "label": "What helped, even a little:"}, {"id": "f3", "type": "textarea", "label": "What I need more of this week:"}]'::jsonb, array['grief and loss', 'self-monitoring', 'support']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('unhelpful-should-have-thoughts-sheet', 'Unhelpful Should-Have Thoughts Sheet', 'cbt'::resource_kind, 'A CBT sheet for looking at "if only" and "I should have" thoughts after a loss with kindness.', 'Use it to help a client meet self-blame after a loss with a fairer view.', array['Adults']::text[], '25 minutes', 'Let the client write the "if only" thoughts as they are. Then look at what they knew at the time and what a compassionate friend would say. The goal is not to remove the pain but to loosen blame.', '[{"id": "f0", "type": "textarea", "label": "An \"if only\" or \"I should have\" thought:"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend who thought this:"}, {"id": "f3", "type": "textarea", "label": "A kinder way to hold this thought:"}]'::jsonb, array['grief and loss', 'guilt', 'self-compassion']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('honoring-their-values-in-my-week-page', 'Honoring Their Values in My Week Page', 'act'::resource_kind, 'An ACT page for finding ways to carry what the client loved about the person or thing lost into daily life.', 'Use it to help a client keep a bond with what they lost while moving through the days.', array['Adults']::text[], '25 minutes', 'Ask what the person or thing meant and what values the client shares with them. Look for one small way to honor those values this week. Make room for sadness in the plan.', '[{"id": "f0", "type": "textarea", "label": "What I loved or valued about them:"}, {"id": "f1", "type": "textarea", "label": "A value I share with them:"}, {"id": "f2", "type": "textarea", "label": "A small way to honor it this week:"}, {"id": "f3", "type": "textarea", "label": "What I will let myself feel while I do:"}]'::jsonb, array['grief and loss', 'values', 'committed action']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('getting-through-anniversary-days-skill-plan', 'Getting Through Anniversary Days Skill Plan', 'dbt'::resource_kind, 'A DBT plan for hard dates, with skills, supports and a gentle schedule.', 'Use it to help a client prepare for a date that is likely to be heavy.', array['Adults']::text[], '25 minutes', 'Choose a coming date and plan the day: who will be near, what to do and not do, and which skills to use. Include rest and a way to honor the person if wanted. If thoughts of ending life arise, share that 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "The date and why it is hard:"}, {"id": "f1", "type": "textarea", "label": "Who will be near or reachable:"}, {"id": "f2", "type": "textarea", "label": "Skills and activities I will use:"}, {"id": "f3", "type": "textarea", "label": "Support any time: 988 (call or text). Who else can I reach?"}]'::jsonb, array['grief and loss', 'distress tolerance', 'safety']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('remembering-box-craft-for-missing-someone', 'Remembering Box Craft for Missing Someone', 'kids'::resource_kind, 'Children decorate a box and fill it with drawings and objects that remind them of someone they miss.', 'Use it to give a child a safe place to hold memories and feelings after a loss.', array['Children']::text[], '40 minutes', 'Provide a box, art supplies and room for the child to choose what goes in. The parent joins, shares a memory and answers questions simply and honestly. Let the child lead and be ready for tears or silence.', '[{"id": "f0", "type": "textarea", "label": "Draw something you remember about the person:"}, {"id": "f1", "type": "textarea", "label": "A thing I would put in the box:"}, {"id": "f2", "type": "textarea", "label": "A feeling I notice when I look in it:"}, {"id": "f3", "type": "textarea", "label": "What my parent and I want to remember together:"}]'::jsonb, array['grief and loss', 'kids', 'art']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('pattern-map-of-a-recurring-conflict', 'Pattern Map of a Recurring Conflict', 'worksheet'::resource_kind, 'A map tracing the steps of a recurring conflict from trigger to aftermath.', 'Use it to help a client see their part in a familiar cycle and where it could change.', array['Adults']::text[], '30 minutes', 'Pick one recurring conflict and map the trigger, what each person feels, what each does and how it ends. Look for the step where the client has a choice. Keep blame out of the map.', '[{"id": "f0", "type": "textarea", "label": "What usually starts it:"}, {"id": "f1", "type": "textarea", "label": "What I feel and what I do:"}, {"id": "f2", "type": "textarea", "label": "What the other person seems to feel and do:"}, {"id": "f3", "type": "textarea", "label": "A step in the cycle where I could try something different:"}]'::jsonb, array['relationship issues', 'conflict', 'formulation']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('assumptions-in-relationships-check-sheet', 'Assumptions in Relationships Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for naming assumptions about a partner or friend and checking them out.', 'Use it to help a client test assumptions rather than act on them.', array['Adults']::text[], '20 minutes', 'Name a recent moment and the assumption the client made about the other person''s motives. Brainstorm other explanations and plan a kind way to ask. Rehearse the question aloud.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "The assumption I made about their motives:"}, {"id": "f2", "type": "textarea", "label": "Other possible explanations:"}, {"id": "f3", "type": "textarea", "label": "A kind way I can ask:"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('how-i-want-to-show-up-with-them-sheet', 'How I Want to Show Up With Them Sheet', 'act'::resource_kind, 'An ACT sheet for naming what the client wants to stand for in a relationship and acting on it when upset.', 'Use it to help a client act on how they want to show up in a relationship.', array['Adults']::text[], '25 minutes', 'Ask what they want to be like as a partner or friend. Compare it with what they do under stress. Choose one value-based action for a coming conversation.', '[{"id": "f0", "type": "textarea", "label": "How I want to show up in this relationship:"}, {"id": "f1", "type": "textarea", "label": "What I do when I am upset:"}, {"id": "f2", "type": "textarea", "label": "A value-based action for the next hard moment:"}, {"id": "f3", "type": "textarea", "label": "What I will do if I slip back into old habits:"}]'::jsonb, array['relationship issues', 'values', 'workability']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('dear-man-script-builder-for-a-hard-ask', 'DEAR MAN Script Builder for a Hard Ask', 'dbt'::resource_kind, 'A DBT builder for writing out a request using describe, express, assert, reinforce, mindful, appear confident and negotiate.', 'Use it to help a client prepare a clear request for a conversation.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client choose one real request and write each DEAR MAN step. Rehearse aloud twice, once with an easy reply and once with a pushback. Adjust the script after each.', '[{"id": "f0", "type": "textarea", "label": "The facts I will describe:"}, {"id": "f1", "type": "textarea", "label": "How I feel and what I am asking for:"}, {"id": "f2", "type": "textarea", "label": "What I will say if they push back:"}, {"id": "f3", "type": "textarea", "label": "What is in it for them, and what I can give:"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('repair-after-a-fight-conversation-guide', 'Repair After a Fight Conversation Guide', 'couples'::resource_kind, 'Partners follow a short guide to repair after an argument: each shares feelings, their part, and what they need.', 'Use it to help partners reconnect after a conflict.', array['Couples']::text[], '30 minutes', 'Wait until both are calm. Each shares how they felt, takes responsibility for a part and says what they need. Do not decide who was right. End with a small act of care.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I felt and my part:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I felt and my part:"}, {"id": "f2", "type": "textarea", "label": "What each of us needs going forward:"}, {"id": "f3", "type": "textarea", "label": "A small act of care we will do now:"}]'::jsonb, array['relationship issues', 'couples', 'repair', 'Gottman']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('circle-of-support-mapping-sheet', 'Circle of Support Mapping Sheet', 'worksheet'::resource_kind, 'A sheet for mapping the people and services a client can turn to, arranged by closeness.', 'Use it to help a client see the support available to them now.', array['Adults', 'Teens']::text[], '25 minutes', 'The client places names, services or groups on rings by how safe and helpful they feel. Do not ask about the abuse itself. Notice gaps and plan one step to widen or strengthen a ring. Respect their pace and choice about who knows what.', '[{"id": "f0", "type": "textarea", "label": "People I feel safest with:"}, {"id": "f1", "type": "textarea", "label": "Services or groups I could turn to:"}, {"id": "f2", "type": "textarea", "label": "A gap I notice in my support:"}, {"id": "f3", "type": "textarea", "label": "One step I can take to strengthen it:"}]'::jsonb, array['sexual abuse', 'support', 'safety']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('safe-thoughts-for-today-sheet', 'Safe Thoughts for Today Sheet', 'cbt'::resource_kind, 'A CBT sheet for noticing present-focused thoughts about safety and choosing ones that fit what is true now.', 'Use it to help a client steady thinking in the present without revisiting details.', array['Adults']::text[], '20 minutes', 'Keep the focus on today: what is happening, who is around and what is safe. Do not ask for details of past events. Help the client choose steady statements that are true now. Pace gently and stop if distress rises.', '[{"id": "f0", "type": "textarea", "label": "A thought that unsettled me today:"}, {"id": "f1", "type": "textarea", "label": "What is true in my life right now:"}, {"id": "f2", "type": "textarea", "label": "A steadier thought that fits the facts today:"}, {"id": "f3", "type": "textarea", "label": "What I can do to feel a bit safer:"}]'::jsonb, array['sexual abuse', 'stabilizing', 'grounding']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('choosing-direction-at-my-own-pace-sheet', 'Choosing Direction at My Own Pace Sheet', 'act'::resource_kind, 'An ACT sheet for choosing valued steps in daily life while setting the pace and limits the client needs.', 'Use it to help a client move toward what matters while staying in charge of their pace.', array['Adults']::text[], '25 minutes', 'Make clear that the client decides what to share and how fast. Focus on present values such as trust, rest and connection, and choose a small action. Include what they need to say no to.', '[{"id": "f0", "type": "textarea", "label": "What matters to me in my life now:"}, {"id": "f1", "type": "textarea", "label": "A small step I want to take:"}, {"id": "f2", "type": "textarea", "label": "Limits I need so it feels safe:"}, {"id": "f3", "type": "textarea", "label": "Who I can tell about my plan:"}]'::jsonb, array['sexual abuse', 'values', 'pacing']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('safe-boundaries-skill-practice-card', 'Safe Boundaries Skill Practice Card', 'dbt'::resource_kind, 'A DBT card for practicing saying no, asking for space and ending a conversation.', 'Use it to help a client practice protecting their own boundaries with firmness and care.', array['Adults', 'Teens']::text[], '25 minutes', 'Rehearse simple lines such as "I am not comfortable with that" in low-stakes role plays. The client chooses which to practice. Notice and name any body signals. Support any decision to stop.', '[{"id": "f0", "type": "textarea", "label": "A situation where I want to protect my boundary:"}, {"id": "f1", "type": "textarea", "label": "A line I can say:"}, {"id": "f2", "type": "textarea", "label": "How my body feels when I say it:"}, {"id": "f3", "type": "textarea", "label": "Who I can talk to afterward:"}]'::jsonb, array['sexual abuse', 'boundaries', 'interpersonal effectiveness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('safe-adults-hand-drawing-activity', 'Safe Adults Hand Drawing Activity', 'kids'::resource_kind, 'Children trace a hand and write or draw a trusted grown-up on each finger.', 'Use it to help a child know who to go to if something feels unsafe or confusing.', array['Children']::text[], '25 minutes', 'Trace the child''s hand and ask for five trusted adults, one per finger. Do not ask about anything that has happened. Remember your reporting duties if a child discloses, and follow your local requirements. The parent reviews the hand and promises to listen.', '[{"id": "f0", "type": "textarea", "label": "Draw your hand and the five people who help you feel safe:"}, {"id": "f1", "type": "textarea", "label": "A grown-up I can tell if something feels wrong:"}, {"id": "f2", "type": "textarea", "label": "What I can say if I need help:"}, {"id": "f3", "type": "textarea", "label": "What my parent promised to do if I tell them:"}]'::jsonb, array['sexual abuse', 'kids', 'safety']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('coping-skills-field-test-log', 'Coping Skills Field Test Log', 'worksheet'::resource_kind, 'A log for trying a coping skill in real life and rating how much it helped.', 'Use it to help a client find which skills actually work for them.', array['Adults', 'Teens']::text[], 'Two weeks', 'Choose three skills and have the client try each a few times, rating distress before and after. Review which suited which situation. Drop what does not help without blame.', '[{"id": "f0", "type": "textarea", "label": "The skill I tried and the situation:"}, {"id": "f1", "type": "textarea", "label": "Distress before and after (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What helped or got in the way:"}, {"id": "f3", "type": "textarea", "label": "Skills I will keep in my toolkit:"}]'::jsonb, array['coping skills', 'skills', 'self-monitoring']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('pocket-coping-statement-card-builder', 'Pocket Coping Statement Card Builder', 'cbt'::resource_kind, 'A builder for writing short coping thoughts on index cards for use in hard moments.', 'Use it to help a client have realistic, kind statements ready when stress hits.', array['Adults', 'Teens']::text[], '20 minutes', 'Help the client write three or four short statements they actually believe, such as "This is hard and I can take one step." Avoid cheerleading that rings false. Test them in role play and revise wording.', '[{"id": "f0", "type": "textarea", "label": "A stressful situation I face:"}, {"id": "f1", "type": "textarea", "label": "A thought that makes it harder:"}, {"id": "f2", "type": "textarea", "label": "A coping thought I believe:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the cards:"}]'::jsonb, array['coping skills', 'self-talk', 'core CBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('choosing-skills-by-values-sheet', 'Choosing Skills by Values Sheet', 'act'::resource_kind, 'An ACT sheet for picking coping actions that also move the client toward something that matters.', 'Use it to help a client choose coping that fits their values and not only relief.', array['Adults']::text[], '25 minutes', 'Ask whether each coping action brings short-term relief, long-term cost, or movement toward values. Look for ones that do the last. Pick one to add to the week.', '[{"id": "f0", "type": "textarea", "label": "Ways I cope when stress is high:"}, {"id": "f1", "type": "textarea", "label": "Which bring relief but cost me later?"}, {"id": "f2", "type": "textarea", "label": "Which move me toward what matters?"}, {"id": "f3", "type": "textarea", "label": "One I will add this week:"}]'::jsonb, array['coping skills', 'values', 'workability']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('accepts-distraction-skill-menu', 'ACCEPTS Distraction Skill Menu', 'dbt'::resource_kind, 'A menu of ACCEPTS distraction skills to ride out a hard stretch without making things worse.', 'Use it to help a client build a menu of ways to get through a hard hour.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through each letter and pick one idea per category the client would actually do. Practice one in session. Remind that distraction is for riding out intensity and then returning to the problem.', '[{"id": "f0", "type": "textarea", "label": "Activities or contributions I could try:"}, {"id": "f1", "type": "textarea", "label": "Comparisons, emotions or thoughts that shift my focus:"}, {"id": "f2", "type": "textarea", "label": "Sensations that help (cold, music, movement):"}, {"id": "f3", "type": "textarea", "label": "The first three I will try:"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('act-out-the-skill-guessing-game', 'Act Out the Skill Guessing Game', 'game'::resource_kind, 'Players act out a coping skill without words while others guess it and say when they might use it.', 'Use it to help a group learn and remember coping skills through play.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Prepare cards naming simple skills. Players act them out, the group guesses and the actor says when it might help. Keep the tone fun. Debrief which skills players might try.', '[{"id": "f0", "type": "textarea", "label": "The skill I acted out:"}, {"id": "f1", "type": "textarea", "label": "A time I could use it:"}, {"id": "f2", "type": "textarea", "label": "A skill I learned from someone else:"}, {"id": "f3", "type": "textarea", "label": "The skill I will try this week:"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('fear-ladder-building-sheet', 'Fear Ladder Building Sheet', 'worksheet'::resource_kind, 'A sheet for listing situations tied to a fear and ranking them in small steps from easiest to hardest.', 'Use it to help a client plan graded steps toward what they avoid.', array['Adults', 'Teens']::text[], '30 minutes', 'List ten situations related to the fear and rate each from 0 to 100. Fill in steps so no jump is too big. Choose a first step the client agrees to try and plan when and how.', '[{"id": "f0", "type": "textarea", "label": "The thing I fear and avoid:"}, {"id": "f1", "type": "textarea", "label": "Situations connected to it, with a rating (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "My ladder from easiest to hardest:"}, {"id": "f3", "type": "textarea", "label": "The first step and when I will try it:"}]'::jsonb, array['phobias', 'hierarchy', 'exposure']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('fear-prediction-versus-outcome-record', 'Fear Prediction Versus Outcome Record', 'cbt'::resource_kind, 'A CBT record comparing what the client feared would happen with what happened during a step.', 'Use it to help a client check fearful predictions against real outcomes.', array['Adults', 'Teens']::text[], 'Per step', 'Before each step, the client writes what they expect and how sure they are. Afterward, they write what happened. Look for gaps and discuss what they learned. Stay with it even when the outcome is mixed.', '[{"id": "f0", "type": "textarea", "label": "What I expect will happen and how sure I am (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "The step I took:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "What I learned about my fear:"}]'::jsonb, array['phobias', 'predictions', 'behavioral experiment']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('approaching-fear-with-willingness-sheet', 'Approaching Fear With Willingness Sheet', 'act'::resource_kind, 'An ACT sheet for approaching a feared situation because of a value, with fear along for the ride.', 'Use it to help a client take steps toward a feared thing for something they care about.', array['Adults']::text[], '25 minutes', 'Link the feared situation to something valued, such as travel or visiting family. Rate willingness and choose a size of step that fits. Plan to carry the fear along and review what happened.', '[{"id": "f0", "type": "textarea", "label": "What I care about that this fear gets in the way of:"}, {"id": "f1", "type": "textarea", "label": "A step toward it:"}, {"id": "f2", "type": "textarea", "label": "The fear I will bring along:"}, {"id": "f3", "type": "textarea", "label": "What happened and what I noticed:"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('calming-skills-before-and-during-a-step-card', 'Calming Skills Before and During a Step Card', 'dbt'::resource_kind, 'A DBT card for using paced breathing, self-soothing and a short mindful focus around an approach step.', 'Use it to help a client prepare a few calming skills for a hard step.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice each skill in session. Explain that skills help ride discomfort and are not meant to make fear vanish before starting. Have the client choose two for their next step.', '[{"id": "f0", "type": "textarea", "label": "The step I plan to take:"}, {"id": "f1", "type": "textarea", "label": "The skills I will use before it:"}, {"id": "f2", "type": "textarea", "label": "The skill I will use during it:"}, {"id": "f3", "type": "textarea", "label": "What worked afterward:"}]'::jsonb, array['phobias', 'distress tolerance', 'self-soothing']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('brave-steps-staircase-drawing-activity', 'Brave Steps Staircase Drawing Activity', 'kids'::resource_kind, 'Children draw a staircase where each step is a small brave action and add stickers as they try each one.', 'Use it to help a child take small steps toward a fear in a playful, visible way.', array['Children']::text[], '30 minutes', 'The child draws a staircase and names small steps toward the feared thing, from looking at a picture to coming closer. The parent cheers each step, never pushes beyond what the child chose and does not give extra reassurance.', '[{"id": "f0", "type": "textarea", "label": "Draw your staircase and write a brave step on each one:"}, {"id": "f1", "type": "textarea", "label": "The first step I will try:"}, {"id": "f2", "type": "textarea", "label": "How my body feels when I am brave:"}, {"id": "f3", "type": "textarea", "label": "How my parent will cheer me on:"}]'::jsonb, array['phobias', 'kids', 'hierarchy']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('appreciating-what-my-body-does-page', 'Appreciating What My Body Does Page', 'worksheet'::resource_kind, 'A page for listing what the body does that the client values, from carrying them to enjoying a favorite song.', 'Use it to help a client notice and value what their body does for them.', array['Adults', 'Teens']::text[], '20 minutes', 'Shift the focus from appearance to function and experience. Ask what the body lets the client do, feel and share with others. Encourage specific and sensory examples. Avoid talk of size or shape.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do that I value:"}, {"id": "f1", "type": "textarea", "label": "A moment this week when my body felt good to be in:"}, {"id": "f2", "type": "textarea", "label": "A person or activity my body helps me enjoy:"}, {"id": "f3", "type": "textarea", "label": "One way I will thank my body this week:"}]'::jsonb, array['body image', 'appreciation', 'self-compassion']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('appearance-thought-check-sheet', 'Appearance Thought Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for catching appearance-related thoughts and the rules behind them.', 'Use it to help a client notice harsh thoughts about how they look and the rules that go with them.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client write the thought, the situation and the rule behind it, such as "I can not go out unless...". Explore the cost of the rule and a fairer thought. Do not discuss numbers, size or measurements.', '[{"id": "f0", "type": "textarea", "label": "The thought about how I look and when it shows up:"}, {"id": "f1", "type": "textarea", "label": "The rule behind it:"}, {"id": "f2", "type": "textarea", "label": "What the rule costs me:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought I could try:"}]'::jsonb, array['body image', 'thinking traps', 'self-criticism']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('living-fully-beyond-appearance-values-sheet', 'Living Fully Beyond Appearance Values Sheet', 'act'::resource_kind, 'An ACT sheet for naming what the client would do more of if appearance worries took up less room.', 'Use it to help a client reconnect with activities they have put off because of how they feel about their body.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client has avoided, such as swimming, photos or going out. Choose one valued activity and plan a small step. Make room for self-conscious feelings in the plan.', '[{"id": "f0", "type": "textarea", "label": "Activities I have avoided because of how I feel about my body:"}, {"id": "f1", "type": "textarea", "label": "What I would value about doing one of them:"}, {"id": "f2", "type": "textarea", "label": "A small step and when I will take it:"}, {"id": "f3", "type": "textarea", "label": "The feelings I will bring along:"}]'::jsonb, array['body image', 'values', 'committed action']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('body-neutral-mindfulness-practice-card', 'Body Neutral Mindfulness Practice Card', 'dbt'::resource_kind, 'A DBT mindfulness card for describing the body in plain, neutral words without praise or criticism.', 'Use it to help a client practice observing without judging in a calm way.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice describing sensations in neutral terms, such as warm hands and steady breath, using one-mind and nonjudgmental skills. Notice when judgments arise and let them pass. Stay with function and sensation.', '[{"id": "f0", "type": "textarea", "label": "Neutral words I can use to describe what I feel:"}, {"id": "f1", "type": "textarea", "label": "A judgment that showed up, and how I let it pass:"}, {"id": "f2", "type": "textarea", "label": "What it was like to observe without judging:"}, {"id": "f3", "type": "textarea", "label": "When I will practice this week:"}]'::jsonb, array['body image', 'mindfulness', 'core DBT']::text[], '2026-11-10T15:00:00+00:00'::timestamptz),
  ('partner-words-that-help-conversation-guide', 'Partner Words That Help Conversation Guide', 'couples'::resource_kind, 'Partners talk about the kinds of comments about appearance that help and those that do not.', 'Use it to help partners talk kindly about how each feels about themselves and about compliments.', array['Couples']::text[], '30 minutes', 'Each partner shares what they find supportive and what feels unhelpful when appearance comes up. Agree on a few words that help and a few topics to leave aside. Keep it about feelings, not numbers or comparisons.', '[{"id": "f0", "type": "textarea", "label": "Partner A: comments that help, and ones that do not:"}, {"id": "f1", "type": "textarea", "label": "Partner B: comments that help, and ones that do not:"}, {"id": "f2", "type": "textarea", "label": "Words we will use when one of us feels low:"}, {"id": "f3", "type": "textarea", "label": "Topics we will leave out of our talks:"}]'::jsonb, array['body image', 'couples', 'support']::text[], '2026-11-10T15:00:00+00:00'::timestamptz)
